        debug(req, "Attempting to delete request:", requestId);

        // Get the request to check permissions and existence
        const [request] = await db
          .select()
          .from(purchaseRequests)
          .where(eq(purchaseRequests.id, requestId))
          .limit(1);

        if (!request) {
          throw new AppError("Request not found", 404);
        }

        // Check if request has any approvals
        const existingApprovals = await db
          .select()
          .from(approvals)
          .where(
            and(
              eq(approvals.requestId, requestId),
              eq(approvals.status, "approved")
            )
          );

        // Permission logic:
        // 1. If request has approved approvals, only admin can delete
        // 2. If request has no approved approvals, requester can delete their own request
        // 3. Admin can always delete
        const hasApprovedApprovals = existingApprovals.length > 0;

        if (hasApprovedApprovals) {
          // Request has approved approvals - only admin can delete
          if (req.user!.role !== "admin") {
            throw new AppError("Cannot delete request with approved approvals. Only admin can delete approved requests.", 403);
          }
        } else {
          // Request has no approved approvals - allow requester or admin to delete
          if (req.user!.role !== "admin" && request.requesterId !== req.user!.id) {
            throw new AppError("Unauthorized to delete this request", 403);
          }
        }

        // Start deletion process
        try {
          // Delete associated records first
          await db.transaction(async (tx) => {
            // Delete notifications first (foreign key constraint)
            await tx
              .delete(notifications)
              .where(eq(notifications.requestId, requestId));

            // Delete approvals
            await tx
              .delete(approvals)
              .where(eq(approvals.requestId, requestId));

            // Get attachments before deleting records
            const attachments = await tx
              .select()
              .from(fileAttachments)
              .where(eq(fileAttachments.requestId, requestId));

            // Delete attachment records
            await tx
              .delete(fileAttachments)
              .where(eq(fileAttachments.requestId, requestId));

            // Delete the request
            await tx
              .delete(purchaseRequests)
              .where(eq(purchaseRequests.id, requestId));

            // After successful database deletion, delete physical files
            for (const attachment of attachments) {
              const filePath = path.join(
                process.cwd(),
                attachment.fileUrl.replace(/^\/uploads\//, "uploads/"),
              );
              try {
                await fs.unlink(filePath);
              } catch (error) {
                console.error(`Failed to delete file ${filePath}:`, error);
                // Continue with other files even if one fails
              }
            }
          });

          // Log the successful deletion in audit log
          await logAuditEvent(req, {
            userId: req.user!.id,
            action: "request_deleted" as AuditAction,
            resourceId: requestId,
            resourceType: "purchase_request",
            details: {
              requestNumber: request.requestNumber,
              deletedAt: new Date().toISOString(),
              deletedBy: req.user!.username,
            },
          });

          debug(req, `Request ${requestId} deleted successfully`);
          res.json({
            success: true,
            message: "Request deleted successfully",
            requestId: requestId,
          });
        } catch (error) {
          debug(req, "Error during deletion transaction:", error);
          throw new DatabaseError(
            "Failed to delete request and associated records",
          );
        }
      } catch (error) {
        debug(req, "Error in delete request endpoint:", error);
        next(error);
      }
    },
  );

