import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import { CheckCircle2, XCircle, Clock, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useUser } from "@/hooks/use-user";
import { useState } from "react";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { cn } from "@/lib/utils";

interface ApprovalAction {
  requestId: number;
  status: "approved" | "rejected" | "changes_requested";
  comments?: string;
  department: string;
}

interface ApprovalFlowProps {
  request: {
    id: number;
    status: string;
    requesterId: number;
    title: string;
    additionalApprovers?: string[];
    approvals?: Array<{
      id: number;
      status: string;
      department: string;
      comments?: string;
      processedAt: string;
      approver: {
        username: string;
      };
    }>;
  };
  onApprovalUpdate?: () => void;
}

export default function ApprovalFlow({
  request,
  onApprovalUpdate
}: ApprovalFlowProps) {
  const { user } = useUser();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [comments, setComments] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Required departments for approval
  const requiredDepartments = ['CEO Office', 'Finance', 'Director'];

  // Additional approvers from the request
  const additionalApprovers = request.additionalApprovers || [];

  // All required approvers (mandatory + additional)
  const allRequiredDepartments = [...requiredDepartments, ...additionalApprovers];

  // Cannot approve own requests
  const isOwnRequest = request.requesterId === user?.id;

  // Check if user's department is required and hasn't approved yet
  const canApprove = user?.department &&
    allRequiredDepartments.includes(user.department) &&
    !isOwnRequest &&
    request.status === 'pending' &&
    !request.approvals?.some(a => a.department === user.department);

  const approvalMutation = useMutation({
    mutationFn: async (data: ApprovalAction) => {
      if (!data.requestId || !data.status || !data.department) {
        throw new Error("Missing required fields for approval");
      }

      const response = await fetch(`/api/requests/${data.requestId}/approvals`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          status: data.status,
          department: data.department,
          comments: data.comments?.trim() || undefined
        }),
        credentials: 'include'
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(errorText || `Failed to process approval: ${response.status}`);
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/requests"] });
      setComments("");
      setIsSubmitting(false);

      toast({
        title: "Success",
        description: "Your approval decision has been recorded",
        variant: "default",
      });

      onApprovalUpdate?.();
    },
    onError: (error: Error) => {
      setIsSubmitting(false);
      toast({
        title: "Approval Failed",
        description: error.message || "Failed to process approval. Please try again.",
        variant: "destructive",
      });
    }
  });

  const handleApproval = async (status: "approved" | "rejected" | "changes_requested") => {
    if (!user?.department || !user?.id) {
      toast({
        title: "Error",
        description: "Department information is missing",
        variant: "destructive",
      });
      return;
    }

    if (!request.id) {
      toast({
        title: "Error",
        description: "Invalid request ID",
        variant: "destructive",
      });
      return;
    }

    if (isSubmitting) {
      toast({
        description: "Please wait while the previous action completes",
        variant: "default"
      });
      return;
    }

    if (!canApprove) {
      toast({
        title: "Permission Denied",
        description: "You don't have permission to approve this request",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsSubmitting(true);
      toast({
        description: `Processing ${status.replace('_', ' ')} action...`,
        variant: "default"
      });

      await approvalMutation.mutateAsync({
        requestId: request.id,
        status,
        comments: comments.trim() || undefined,
        department: user.department
      });
    } catch (error) {
      console.error('Error in handleApproval:', error);
      // Error handling is done in mutation's onError
    }
  };

  // Create a deduplicated list of departments to prevent duplicates
  const uniqueDepartments = Array.from(new Set(allRequiredDepartments));

  // Get approval status for each unique department
  const departmentStatuses = uniqueDepartments.map(dept => {
    const approval = request.approvals?.find(a => a.department === dept);
    return {
      department: dept,
      status: approval?.status || 'pending',
      approver: approval?.approver?.username,
      processedAt: approval?.processedAt,
      comments: approval?.comments,
      isAdditional: !requiredDepartments.includes(dept)
    };
  });

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h4 className="font-medium">Department Approvals</h4>
      </div>

      <div className="grid gap-4">
        {departmentStatuses.map(({ department, status, approver, processedAt, comments, isAdditional }) => (
          <Card key={department} className={cn(
            "transition-colors",
            status === 'approved' ? "border-green-200 bg-green-50" :
              status === 'rejected' ? "border-red-200 bg-red-50" :
                status === 'changes_requested' ? "border-orange-200 bg-orange-50" :
                  "border-gray-200"
          )}>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-4">
                  {status === 'approved' ? (
                    <CheckCircle2 className="h-5 w-5 text-green-500" />
                  ) : status === 'rejected' ? (
                    <XCircle className="h-5 w-5 text-red-500" />
                  ) : status === 'changes_requested' ? (
                    <AlertTriangle className="h-5 w-5 text-orange-500" />
                  ) : (
                    <Clock className="h-5 w-5 text-blue-500" />
                  )}
                  <div>
                    <div className="flex items-center gap-2">
                      <p className="font-medium">{department}</p>
                      <Badge variant="outline" className={cn(
                        "text-xs",
                        isAdditional ? "bg-purple-100 text-purple-700 border-purple-200" : "text-gray-700"
                      )}>
                        {isAdditional ? "Additional" : "Required"}
                      </Badge>
                    </div>
                    {approver && (
                      <p className="text-sm text-gray-500">Processed by: {approver}</p>
                    )}
                  </div>
                </div>
                <div className="flex items-center space-x-4">
                  <Badge
                    className={cn(
                      status === 'approved' ? "bg-green-100 text-green-700 border-green-200" :
                        status === 'rejected' ? "bg-red-100 text-red-700 border-red-200" :
                          status === 'changes_requested' ? "bg-orange-100 text-orange-700 border-orange-200" :
                            "bg-blue-100 text-blue-700 border-blue-200"
                    )}
                  >
                    {status === 'changes_requested' ? 'CHANGES REQUESTED' : status.toUpperCase()}
                  </Badge>
                </div>
              </div>
              {comments && (
                <div className="mt-3 text-sm text-gray-600 bg-white/50 p-3 rounded-md">
                  <p className="font-medium text-xs text-gray-500 mb-1">Comments:</p>
                  {comments}
                </div>
              )}
              {processedAt && (
                <p className="mt-2 text-xs text-gray-500">
                  {format(new Date(processedAt), "PPp")}
                </p>
              )}
            </CardContent>
          </Card>
        ))}

        {canApprove && (
          <Card className="border-blue-200 bg-blue-50/50">
            <CardContent className="p-4">
              <h5 className="font-medium mb-3">Process Request</h5>
              <div className="space-y-4">
                <Textarea
                  placeholder="Add comments (optional)"
                  value={comments}
                  onChange={(e) => setComments(e.target.value)}
                  className="w-full bg-white"
                  disabled={isSubmitting}
                />
                <div className="flex flex-wrap gap-3">
                  <Button
                    onClick={() => handleApproval("approved")}
                    disabled={isSubmitting}
                    className="bg-green-600 hover:bg-green-700 text-white"
                  >
                    <CheckCircle2 className="h-4 w-4 mr-2" />
                    {isSubmitting ? "Processing..." : "Approve"}
                  </Button>
                  <Button
                    onClick={() => handleApproval("rejected")}
                    disabled={isSubmitting}
                    variant="destructive"
                  >
                    <XCircle className="h-4 w-4 mr-2" />
                    {isSubmitting ? "Processing..." : "Reject"}
                  </Button>
                  <Button
                    onClick={() => handleApproval("changes_requested")}
                    disabled={isSubmitting}
                    variant="outline"
                    className="border-orange-200 bg-orange-100 text-orange-700 hover:bg-orange-200"
                  >
                    <AlertTriangle className="h-4 w-4 mr-2" />
                    {isSubmitting ? "Processing..." : "Request Changes"}
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

client/src/components/BrandMoodBoardGene.content:
import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Wand2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface MoodBoardProps {
  companyName?: string;
  primaryColor?: string;
  secondaryColor?: string;
  accentColor?: string;
  onGenerated?: (imageUrls: string[]) => void;
}

export default function BrandMoodBoardGenerator({
  companyName = "",
  primaryColor = "#71569E",
  secondaryColor = "#F0F0FA",
  accentColor = "#191160",
  onGenerated,
}: MoodBoardProps) {
  const { toast } = useToast();
  const [prompt, setPrompt] = useState("");
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);

  const generateMoodboard = useMutation({
    mutationFn: async (data: { prompt: string; colors: string[] }) => {
      const response = await fetch("/api/generate-moodboard", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          prompt: data.prompt,
          colors: [primaryColor, secondaryColor, accentColor],
          companyName,
        }),
        credentials: "include",
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      return response.json();
    },
    onSuccess: (data) => {
      setGeneratedImages(data.images);
      onGenerated?.(data.images);
      toast({
        title: "Success",
        description: "Mood board generated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to generate mood board",
        variant: "destructive",
      });
    },
  });

  const handleGenerateMoodBoard = () => {
    if (!prompt.trim()) {
      toast({
        title: "Error",
        description: "Please enter a description for your brand mood",
        variant: "destructive",
      });
      return;
    }

    generateMoodboard.mutate({
      prompt,
      colors: [primaryColor, secondaryColor, accentColor],
    });
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Brand Mood Board Generator</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-2">
          <Label>Brand Mood Description</Label>
          <Input
            placeholder="e.g. Modern, minimalistic, tech-focused brand that conveys innovation and trust"
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
          />
          <p className="text-sm text-muted-foreground">
            Describe the mood and feel you want for your brand. Our AI will generate a mood board based on your description and brand colors.
          </p>
        </div>

        <Button
          onClick={handleGenerateMoodBoard}
          disabled={generateMoodboard.isPending}
          className="w-full"
        >
          {generateMoodboard.isPending ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : (
            <Wand2 className="mr-2 h-4 w-4" />
          )}
          Generate Mood Board
        </Button>

        {generatedImages.length > 0 && (
          <div className="grid grid-cols-2 gap-4 mt-6">
            {generatedImages.map((image, index) => (
              <div
                key={index}
                className={cn(
                  "relative aspect-square rounded-lg overflow-hidden border",
                  index === 0 && "col-span-2 aspect-[2/1]"
                )}
              >
                <img
                  src={image}
                  alt={`Mood board image ${index + 1}`}
                  className="object-cover w-full h-full"
                />
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/BulkExportButton.t.content:
import { useState } from "react";
import { Button, ButtonProps } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Loader2, FileText, Archive, ChevronDown, Database, Table2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { RequestFilters } from "@/services/requests";
import { 
  exportMultipleRequestsToExcel, 
  exportMultipleRequestsToCSV, 
  exportMultipleRequestsToPDF, 
  exportMultipleRequestsAsZip 
} from "@/lib/exportUtils";

export interface BulkExportButtonProps extends Omit<ButtonProps, "children"> {
  requests: any[];
  filters?: RequestFilters;
  format?: "excel" | "csv" | "pdf" | "zip";
  includeAttachments?: boolean;
  children?: React.ReactNode; 
  onExportComplete?: (fileName: string) => void;
  onExportError?: (error: Error) => void;
}

export function BulkExportButton({
  requests,
  filters,
  format,
  includeAttachments = true,
  className,
  children,
  onExportComplete,
  onExportError,
  ...props
}: BulkExportButtonProps) {
  const [exporting, setExporting] = useState(false);
  const [exportFormat, setExportFormat] = useState<"excel" | "csv" | "pdf" | "zip" | null>(format || null);
  const { toast } = useToast();

  const handleExport = async (selectedFormat: "excel" | "csv" | "pdf" | "zip") => {
    if (!requests || requests.length === 0) {
      toast({
        title: "No requests to export",
        description: "Please select at least one request for export",
      });
      return;
    }

    setExportFormat(selectedFormat);
    setExporting(true);

    try {
      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
      let fileName = `purchase-requests-export-${timestamp}`;

      // Apply any filters provided for filename clarity
      if (filters) {
        if (filters.status?.length) fileName += `-status-${filters.status.join("-")}`;
        if (filters.priority?.length) fileName += `-priority-${filters.priority.join("-")}`;
        if (filters.startDate) fileName += `-from-${filters.startDate}`;
        if (filters.endDate) fileName += `-to-${filters.endDate}`;
      }

      // Add format-specific extension to the filename
      let fileExtension = '';
      switch (selectedFormat) {
        case "excel":
          fileExtension = '.xlsx';
          break;
        case "csv":
          fileExtension = '.csv';
          break;
        case "pdf":
        case "zip":
          fileExtension = '.zip';
          break;
      }

      fileName += fileExtension;

      // Show toast to inform user we're starting the export
      toast({
        title: "Starting Export",
        description: `Preparing ${requests.length} requests for export as ${selectedFormat.toUpperCase()}...`,
      });

      let exportedFileName: string;

      // Use the appropriate export function based on format
      try {
        console.log(`Starting ${selectedFormat} export for ${requests.length} requests`);

        switch (selectedFormat) {
          case "excel":
            exportedFileName = await exportMultipleRequestsToExcel(requests);
            break;
          case "csv":
            exportedFileName = await exportMultipleRequestsToCSV(requests);
            break;
          case "pdf":
            exportedFileName = await exportMultipleRequestsToPDF(requests);
            break;
          case "zip":
            exportedFileName = await exportMultipleRequestsAsZip(requests, includeAttachments);
            break;
          default:
            throw new Error(`Unsupported export format: ${selectedFormat}`);
        }

        // If we get here, the export functions successfully triggered a download
        console.log(`Export completed successfully as: ${exportedFileName}`);

        // Export was successful if we reached this point
        toast({
          title: "Export Complete",
          description: `Successfully exported ${requests.length} requests as ${selectedFormat.toUpperCase()}`,
        });

        if (onExportComplete) {
          // Use the actual filename returned by the export function
          onExportComplete(exportedFileName || fileName);
        }
      } catch (exportError) {
        console.error(`Error during ${selectedFormat} export:`, exportError);
        throw exportError; // Rethrow to be caught by the outer try/catch
      }
    } catch (error) {
      console.error("Export error:", error);
      toast({
        title: "Export Failed",
        description: error instanceof Error 
          ? error.message 
          : "An unexpected error occurred during export",
        variant: "destructive",
      });

      if (onExportError && error instanceof Error) {
        onExportError(error);
      }
    } finally {
      setExporting(false);
      setExportFormat(null);
    }
  };

  if (format) {
    return (
      <Button
        onClick={() => handleExport(format)}
        disabled={exporting || !requests || requests.length === 0}
        className={className}
        {...props}
      >
        {exporting ? (
          <>
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            Exporting...
          </>
        ) : (
          <>
            {children || (
              <>
                {format === "excel" && <Database className="mr-2 h-4 w-4" />}
                {format === "csv" && <Table2 className="mr-2 h-4 w-4" />}
                {format === "pdf" && <FileText className="mr-2 h-4 w-4" />}
                {format === "zip" && <Archive className="mr-2 h-4 w-4" />}
                Export as {format.toUpperCase()}
              </>
            )}
          </>
        )}
      </Button>
    );
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          disabled={exporting || !requests || requests.length === 0}
          className={className}
          {...props}
        >
          {exporting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Exporting as {exportFormat?.toUpperCase()}...
            </>
          ) : (
            <>
              {children || (
                <>
                  Export
                  <ChevronDown className="ml-2 h-4 w-4" />
                </>
              )}
            </>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuItem onClick={() => handleExport("excel")}>
          <Database className="mr-2 h-4 w-4" />
          Excel (Multi-sheet)
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => handleExport("csv")}>
          <Table2 className="mr-2 h-4 w-4" />
          CSV (Tabular format)
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => handleExport("pdf")}>
          <FileText className="mr-2 h-4 w-4" />
          PDF (ZIP with PDFs)
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => handleExport("zip")}>
          <Archive className="mr-2 h-4 w-4" />
          ZIP {includeAttachments ? "(with attachments)" : ""}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export default BulkExportButton;

client/src/components/ChangePasswordDial.content:
import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { useIsMobile } from "@/hooks/use-mobile";
import { Loader2, Lock } from "lucide-react";

interface ChangePasswordDialogProps {
  userId: number;
  username: string;
  onPasswordChange: () => void;
}

export function ChangePasswordDialog({ userId, username, onPasswordChange }: ChangePasswordDialogProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const isMobile = useIsMobile();
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (password !== confirmPassword) {
      toast({
        title: "Error",
        description: "Passwords do not match",
        variant: "destructive",
      });
      return;
    }

    if (password.length < 6) {
      toast({
        title: "Error",
        description: "Password must be at least 6 characters",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch(`/api/admin/users/${userId}/update-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ password }),
        credentials: "include",
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      toast({
        title: "Success",
        description: "Password updated successfully",
      });

      onPasswordChange();
      setIsOpen(false);
      setPassword("");
      setConfirmPassword("");
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to update password",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button 
          variant="outline" 
          size={isMobile ? "icon" : "sm"}
          title="Change Password"
          className="flex items-center"
        >
          <Lock className="h-4 w-4" />
          {!isMobile && <span className="ml-1">Change Password</span>}
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Change Password for {username}</DialogTitle>
          <DialogDescription>
            Enter a new password for this user. The password must be at least 6 characters long.
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="password">New Password</Label>
              <Input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter new password"
                required
                minLength={6}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="confirmPassword">Confirm Password</Label>
              <Input
                id="confirmPassword"
                type="password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Confirm new password"
                required
                minLength={6}
              />
            </div>
          </div>
          <DialogFooter>
            <Button 
              type="submit" 
              disabled={isLoading || !password || !confirmPassword}
            >
              {isLoading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Updating...
                </>
              ) : (
                'Update Password'
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/ClaudeAIInsights.t.content:
import { useState, useEffect } from 'react';
import { useClaudeAI } from '@/hooks/use-claude-ai';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Loader2, AlertCircle, CheckCircle, BarChart, Building, FileCheck, FileText } from 'lucide-react';

interface ClaudeAIInsightsProps {
  requestData: any;
  vendorOptions?: any[];
  attachmentData?: any;
  showExecutiveSummary?: boolean;
}

/**
 * Component for displaying Claude AI-generated insights about a purchase request
 */
export function ClaudeAIInsights({
  requestData,
  vendorOptions = [],
  attachmentData,
  showExecutiveSummary = false,
}: ClaudeAIInsightsProps) {
  const {
    // Request analysis
    analyzeRequest,
    requestAnalysisStatus,
    requestAnalysisError,

    // Vendor recommendations
    recommendVendors,
    vendorRecommendationStatus,
    vendorRecommendationError,

    // Attachment validation
    validateAttachments,
    attachmentValidationStatus,
    attachmentValidationError,

    // Executive summary
    generateExecutiveSummary,
    executiveSummaryStatus,
    executiveSummaryError,
  } = useClaudeAI();

  // State for storing analysis results
  const [analysis, setAnalysis] = useState<{
    optimizationSuggestions: string[];
    costSavings: string;
    priorityScore: number;
    priorityReason: string;
  } | null>(null);

  // State for storing vendor recommendations
  const [vendorRecommendations, setVendorRecommendations] = useState<{
    recommendedVendors: string[];
    reasonings: Record<string, string>;
  } | null>(null);

  // State for storing attachment validation
  const [attachmentValidation, setAttachmentValidation] = useState<{
    isValid: boolean;
    issues: string[];
    suggestions: string[];
  } | null>(null);

  // State for storing executive summary
  const [executiveSummary, setExecutiveSummary] = useState<string>('');

  // Handler for analyzing request
  const handleAnalyzeRequest = async () => {
    if (!requestData) return;

    const result = await analyzeRequest(requestData);
    setAnalysis(result);
  };

  // Handler for getting vendor recommendations
  const handleRecommendVendors = async () => {
    if (!requestData || !vendorOptions || vendorOptions.length === 0) return;

    const result = await recommendVendors(requestData, vendorOptions);
    setVendorRecommendations(result);
  };

  // Handler for validating attachments
  const handleValidateAttachments = async () => {
    if (!attachmentData) return;

    const result = await validateAttachments(attachmentData);
    setAttachmentValidation(result);
  };

  // Handler for generating executive summary
  const handleGenerateExecutiveSummary = async () => {
    if (!requestData) return;

    const summary = await generateExecutiveSummary(requestData);
    setExecutiveSummary(summary);
  };

  // Function to render the request analysis section
  const renderRequestAnalysis = () => {
    if (requestAnalysisStatus === 'loading') {
      return (
        <div className="flex items-center justify-center p-8">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="ml-2">Analyzing request...</span>
        </div>
      );
    }

    if (requestAnalysisStatus === 'error') {
      return (
        <Alert variant="destructive" className="mt-4">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>
            {requestAnalysisError || 'Failed to analyze request'}
          </AlertDescription>
        </Alert>
      );
    }

    if (analysis) {
      return (
        <div className="space-y-4">
          <div>
            <h4 className="text-sm font-medium">Priority Score</h4>
            <div className="mt-1 flex items-center">
              <div className="relative h-4 w-full rounded-full bg-gray-200 dark:bg-gray-700">
                <div 
                  className="absolute h-4 rounded-full bg-primary" 
                  style={{ width: `${analysis.priorityScore}%` }}
                />
              </div>
              <span className="ml-2 text-sm font-medium">{analysis.priorityScore}</span>
            </div>
            <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
              {analysis.priorityReason}
            </p>
          </div>

          <div>
            <h4 className="text-sm font-medium">Potential Cost Savings</h4>
            <p className="mt-1 text-lg font-bold text-green-600 dark:text-green-400">
              {analysis.costSavings}
            </p>
          </div>

          <div>
            <h4 className="text-sm font-medium">Optimization Suggestions</h4>
            <ul className="mt-2 space-y-2">
              {analysis.optimizationSuggestions.map((suggestion, index) => (
                <li key={index} className="rounded-md bg-gray-50 p-2 text-sm dark:bg-gray-800">
                  {suggestion}
                </li>
              ))}
            </ul>
          </div>
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center p-6">
        <BarChart className="h-12 w-12 text-gray-400" />
        <p className="mt-2 text-center text-sm text-gray-500">
          AI analysis can provide optimization suggestions, cost savings estimates, and
          priority recommendations for this request.
        </p>
        <Button onClick={handleAnalyzeRequest} className="mt-4">
          Analyze Request
        </Button>
      </div>
    );
  };

  // Function to render the vendor recommendations section
  const renderVendorRecommendations = () => {
    if (vendorRecommendationStatus === 'loading') {
      return (
        <div className="flex items-center justify-center p-8">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="ml-2">Finding vendor recommendations...</span>
        </div>
      );
    }

    if (vendorRecommendationStatus === 'error') {
      return (
        <Alert variant="destructive" className="mt-4">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>
            {vendorRecommendationError || 'Failed to get vendor recommendations'}
          </AlertDescription>
        </Alert>
      );
    }

    if (vendorRecommendations) {
      return (
        <div className="space-y-4">
          {vendorRecommendations.recommendedVendors.length > 0 ? (
            vendorRecommendations.recommendedVendors.map((vendor, index) => (
              <div key={index} className="rounded-md border p-4">
                <h4 className="font-medium">{vendor}</h4>
                <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                  {vendorRecommendations.reasonings[vendor] || 'Recommended based on request details'}
                </p>
              </div>
            ))
          ) : (
            <p className="text-center text-sm text-gray-500">
              No vendor recommendations found. Try adjusting your request or adding more vendors.
            </p>
          )}
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center p-6">
        <Building className="h-12 w-12 text-gray-400" />
        <p className="mt-2 text-center text-sm text-gray-500">
          AI can recommend the most suitable vendors for this purchase request based on your requirements.
        </p>
        <Button 
          onClick={handleRecommendVendors} 
          className="mt-4"
          disabled={!vendorOptions || vendorOptions.length === 0}
        >
          Get Vendor Recommendations
        </Button>
        {(!vendorOptions || vendorOptions.length === 0) && (
          <p className="mt-2 text-xs text-gray-500">
            No vendor options available for analysis
          </p>
        )}
      </div>
    );
  };

  // Function to render the attachment validation section
  const renderAttachmentValidation = () => {
    if (attachmentValidationStatus === 'loading') {
      return (
        <div className="flex items-center justify-center p-8">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="ml-2">Validating attachments...</span>
        </div>
      );
    }

    if (attachmentValidationStatus === 'error') {
      return (
        <Alert variant="destructive" className="mt-4">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>
            {attachmentValidationError || 'Failed to validate attachments'}
          </AlertDescription>
        </Alert>
      );
    }

    if (attachmentValidation) {
      return (
        <div className="space-y-4">
          <div className="flex items-center">
            <Badge variant={attachmentValidation.isValid ? 'default' : 'destructive'}>
              {attachmentValidation.isValid ? 'Valid' : 'Issues Found'}
            </Badge>
          </div>

          {attachmentValidation.issues.length > 0 && (
            <div>
              <h4 className="text-sm font-medium">Issues</h4>
              <ul className="mt-2 space-y-2">
                {attachmentValidation.issues.map((issue, index) => (
                  <li key={index} className="rounded-md bg-red-50 p-2 text-sm text-red-700 dark:bg-red-900 dark:text-red-200">
                    {issue}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {attachmentValidation.suggestions.length > 0 && (
            <div>
              <h4 className="text-sm font-medium">Suggestions</h4>
              <ul className="mt-2 space-y-2">
                {attachmentValidation.suggestions.map((suggestion, index) => (
                  <li key={index} className="rounded-md bg-blue-50 p-2 text-sm text-blue-700 dark:bg-blue-900 dark:text-blue-200">
                    {suggestion}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center p-6">
        <FileCheck className="h-12 w-12 text-gray-400" />
        <p className="mt-2 text-center text-sm text-gray-500">
          AI can validate your attachments for completeness and identify any potential issues.
        </p>
        <Button 
          onClick={handleValidateAttachments} 
          className="mt-4"
          disabled={!attachmentData}
        >
          Validate Attachments
        </Button>
        {!attachmentData && (
          <p className="mt-2 text-xs text-gray-500">
            No attachments available for validation
          </p>
        )}
      </div>
    );
  };

  // Function to render the executive summary section
  const renderExecutiveSummary = () => {
    if (executiveSummaryStatus === 'loading') {
      return (
        <div className="flex items-center justify-center p-8">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="ml-2">Generating executive summary...</span>
        </div>
      );
    }

    if (executiveSummaryStatus === 'error') {
      return (
        <Alert variant="destructive" className="mt-4">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>
            {executiveSummaryError || 'Failed to generate executive summary'}
          </AlertDescription>
        </Alert>
      );
    }

    if (executiveSummary) {
      return (
        <div className="space-y-4">
          <div className="rounded-md bg-gray-50 p-4 dark:bg-gray-800">
            <p className="text-sm leading-relaxed">{executiveSummary}</p>
          </div>
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center p-6">
        <FileText className="h-12 w-12 text-gray-400" />
        <p className="mt-2 text-center text-sm text-gray-500">
          AI can generate a concise executive summary for this purchase request,
          highlighting key business impacts and justifications.
        </p>
        <Button onClick={handleGenerateExecutiveSummary} className="mt-4">
          Generate Executive Summary
        </Button>
      </div>
    );
  };

  return (
    <Card className="bg-white dark:bg-gray-900">
      <CardHeader>
        <CardTitle>AI Insights</CardTitle>
        <CardDescription>
          Smart analysis and recommendations for this purchase request powered by Claude AI
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="analysis">
          <TabsList className="grid w-full grid-cols-3 mb-4">
            <TabsTrigger value="analysis">Analysis</TabsTrigger>
            <TabsTrigger value="vendors">Vendors</TabsTrigger>
            <TabsTrigger value="attachments">Attachments</TabsTrigger>
          </TabsList>
          <TabsContent value="analysis" className="min-h-[300px]">
            {renderRequestAnalysis()}
          </TabsContent>
          <TabsContent value="vendors" className="min-h-[300px]">
            {renderVendorRecommendations()}
          </TabsContent>
          <TabsContent value="attachments" className="min-h-[300px]">
            {renderAttachmentValidation()}
          </TabsContent>
        </Tabs>

        {showExecutiveSummary && (
          <>
            <Separator className="my-6" />
            <div>
              <h3 className="text-lg font-medium mb-4">Executive Summary</h3>
              {renderExecutiveSummary()}
            </div>
          </>
        )}
      </CardContent>
      <CardFooter className="flex justify-between bg-gray-50 px-6 py-4 dark:bg-gray-800">
        <div className="flex items-center text-xs text-gray-500">
          <span>Powered by Claude AI</span>
        </div>
      </CardFooter>
    </Card>
  );
}

