import { useState, useEffect } from "react";
import { Check, Clock, AlertCircle, ArrowRight } from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Card } from "@/components/ui/card";
import type { ErrorSeverity } from "@/lib/errorUtils";

interface Stage {
  id: number;
  title: string;
  description: string;
  icon: JSX.Element;
  completed: boolean;
}

interface ErrorProgressTrackerProps {
  errorCode: string;
  severity: ErrorSeverity;
  currentStage: number;
  onStageComplete?: (stageId: number) => void;
}

const severityColors = {
  critical: "text-red-600",
  error: "text-orange-600",
  warning: "text-yellow-600",
  info: "text-blue-600"
} as const;

const severityBgColors = {
  critical: "bg-red-100",
  error: "bg-orange-100",
  warning: "bg-yellow-100",
  info: "bg-blue-100"
} as const;

export default function ErrorProgressTracker({
  errorCode,
  severity,
  currentStage,
  onStageComplete
}: ErrorProgressTrackerProps) {
  const [progress, setProgress] = useState(0);
  const [stages, setStages] = useState<Stage[]>([
    {
      id: 1,
      title: "Error Detected",
      description: "System has identified the error and initiated resolution process",
      icon: <AlertCircle className="h-6 w-6" />,
      completed: false
    },
    {
      id: 2,
      title: "Analysis",
      description: "Analyzing error context and potential solutions",
      icon: <Clock className="h-6 w-6" />,
      completed: false
    },
    {
      id: 3,
      title: "Resolution",
      description: "Implementing solution and verifying fixes",
      icon: <ArrowRight className="h-6 w-6" />,
      completed: false
    },
    {
      id: 4,
      title: "Verification",
      description: "Confirming error has been resolved successfully",
      icon: <Check className="h-6 w-6" />,
      completed: false
    }
  ]);

  useEffect(() => {
    // Update progress based on current stage
    const progressValue = (currentStage / stages.length) * 100;
    const animationDuration = 1000; // 1 second
    const steps = 60; // 60 frames for smooth animation
    const increment = progressValue / steps;
    let currentProgress = 0;

    const interval = setInterval(() => {
      if (currentProgress < progressValue) {
        currentProgress += increment;
        setProgress(Math.min(currentProgress, progressValue));
      } else {
        clearInterval(interval);
      }
    }, animationDuration / steps);

    // Update stages completion status
    setStages(prevStages => 
      prevStages.map(stage => ({
        ...stage,
        completed: stage.id <= currentStage
      }))
    );

    return () => clearInterval(interval);
  }, [currentStage, stages.length]);

  return (
    <Card className="p-6 max-w-2xl mx-auto">
      <div className="mb-4">
        <h3 className="text-lg font-semibold mb-2">
          Error Resolution Progress
          <span className={`ml-2 text-sm ${severityColors[severity]}`}>
            {errorCode}
          </span>
        </h3>
        <Progress 
          value={progress} 
          className="h-2 mb-6"
          indicatorClassName={severityBgColors[severity]}
        />
      </div>

      <div className="space-y-4">
        {stages.map((stage, index) => (
          <div 
            key={stage.id}
            className={`flex items-start space-x-4 p-3 rounded-lg transition-all duration-300 ${
              stage.completed ? `${severityBgColors[severity]} bg-opacity-20` : 'bg-gray-50'
            }`}
          >
            <div className={`
              p-2 rounded-full transition-colors
              ${stage.completed ? severityColors[severity] : 'text-gray-400'}
            `}>
              {stage.icon}
            </div>

            <div className="flex-1">
              <h4 className={`font-medium ${
                stage.completed ? severityColors[severity] : 'text-gray-700'
              }`}>
                {stage.title}
              </h4>
              <p className="text-sm text-gray-600 mt-1">{stage.description}</p>
            </div>

            {stage.completed && (
              <Check className={`h-5 w-5 ${severityColors[severity]} animate-fade-in`} />
            )}
          </div>
        ))}
      </div>
    </Card>
  );
}

client/src/components/ExportDropdown.tsx.content:
import React, { useState } from 'react';
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { FileDown, FileText, Package, PenTool, Download } from "lucide-react";
import { exportRequestToPDF, exportMultipleRequestsAsZip } from "@/lib/exportUtils";
import { useToast } from "@/hooks/use-toast";

interface ExportDropdownProps {
  requestIds?: number[];
  singleRequestId?: number;
  request?: any;
  filters?: Record<string, any>;
  variant?: "default" | "outline" | "secondary";
  size?: "sm" | "default" | "lg";
  exportType?: "single" | "multiple" | "filtered";
  showLabel?: boolean;
  includeReportTypes?: boolean;
}

export function ExportDropdown({
  requestIds = [],
  singleRequestId,
  request,
  filters = {},
  variant = "default",
  size = "default",
  exportType = "single",
  showLabel = true,
  includeReportTypes = false
}: ExportDropdownProps) {
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState<string | null>(null);

  const handleExportSingle = async (format: string, type: 'user' | 'approver' | 'admin' = 'user') => {
    if (!request && !singleRequestId) {
      toast({
        title: "No Request Selected",
        description: "Please select a request to export",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(format);

      // Fetch the request if we only have the ID
      let requestData = request;
      if (!requestData && singleRequestId) {
        try {
          console.log(`Fetching request data for ID: ${singleRequestId}`);
          const response = await fetch(`/api/requests/${singleRequestId}`);
          if (!response.ok) throw new Error('Failed to fetch request data');
          requestData = await response.json();
          console.log('Retrieved request data:', requestData);
        } catch (error) {
          console.error('Error fetching request data:', error);
          toast({
            title: "Error",
            description: "Failed to fetch request data for export",
            variant: "destructive"
          });
          setIsLoading(null);
          return;
        }
      }

      // Early validation to prevent null/undefined requestData
      if (!requestData || typeof requestData !== 'object') {
        throw new Error('Invalid request data for export');
      }

      // PDF and ZIP are the only supported formats now
      console.log(`Using client-side export for ${format}`);
      let fileName = '';
      switch (format) {
        case 'pdf':
          fileName = await exportRequestToPDF(requestData, type);
          break;
        case 'zip':
          fileName = await exportMultipleRequestsAsZip([requestData], true);
          break;
        default:
          throw new Error(`Unsupported format: ${format}`);
      }

      toast({
        title: "Export Successful",
        description: `Successfully exported ${fileName}`
      });
    } catch (error) {
      console.error(`Error exporting to ${format}:`, error);
      toast({
        title: "Export Failed",
        description: error instanceof Error ? error.message : "Failed to export request",
        variant: "destructive"
      });
    } finally {
      setIsLoading(null);
    }
  };

  const handleExportMultiple = async (format: string, type: 'user' | 'approver' | 'admin' = 'user') => {
    if (requestIds.length === 0 && exportType === 'multiple') {
      toast({
        title: "No Requests Selected",
        description: "Please select at least one request to export",
        variant: "destructive"
      });
      return;
    }

    try {
      setIsLoading(format);

      // PDF and ZIP are the only supported formats now
      console.log('Using client-side bulk export for format:', format);

      // For filtered export, we need to pass the filters
      const endpoint = exportType === 'filtered' 
        ? `/api/requests/export/bulk?${new URLSearchParams(Object.entries(filters).reduce((acc, [key, value]) => {
            if (value !== undefined && value !== null) {
              if (Array.isArray(value)) {
                acc[key] = value.join(',');
              } else {
                acc[key] = String(value);
              }
            }
            return acc;
          }, {} as Record<string, string>)).toString()}`
        : `/api/requests/export/bulk?ids=${requestIds.join(',')}`;

      console.log('Fetching requests from endpoint:', endpoint);

      // Fetch data for multiple requests
      let requests = [];
      try {
        const response = await fetch(endpoint);
        if (!response.ok) {
          const errorText = await response.text();
          throw new Error(`Failed to fetch requests data: ${errorText}`);
        }
        const responseData = await response.json();
        console.log('Received data from server:', responseData);

        // Handle different response formats - some endpoints return {data: [...]} structure
        requests = Array.isArray(responseData) ? responseData : 
                  (responseData.data && Array.isArray(responseData.data)) ? responseData.data : [];

        console.log('Processing requests for export:', requests.length, 'items');
      } catch (error) {
        console.error('Error fetching requests data:', error);
        toast({
          title: "Export Error",
          description: error instanceof Error ? error.message : "Failed to fetch requests data for export",
          variant: "destructive"
        });
        setIsLoading(null);
        return;
      }

      if (requests.length === 0) {
        toast({
          title: "No Data",
          description: "No requests found with the current filters"
        });
        setIsLoading(null);
        return;
      }

      let fileName = '';
      switch (format) {
        case 'zip':
          fileName = await exportMultipleRequestsAsZip(requests, true);
          break;
        default:
          throw new Error(`Unsupported bulk format: ${format}`);
      }

      toast({
        title: "Export Successful",
        description: `Successfully exported ${requests.length} requests to ${fileName}`
      });
    } catch (error) {
      console.error(`Error exporting multiple to ${format}:`, error);
      toast({
        title: "Export Failed",
        description: error instanceof Error ? error.message : "Failed to export requests",
        variant: "destructive"
      });
    } finally {
      setIsLoading(null);
    }
  };

  // Determine the export handler based on export type
  const handleExport = (format: string, type: 'user' | 'approver' | 'admin' = 'user') => {
    if (exportType === 'single') {
      handleExportSingle(format, type);
    } else {
      handleExportMultiple(format, type);
    }
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button 
          variant={variant}
          size={size}
          className="gap-2"
          disabled={!!isLoading}
        >
          {isLoading ? (
            <span className="flex items-center gap-2">
              <FileDown className="h-4 w-4 animate-pulse" />
              Exporting...
            </span>
          ) : (
            <>
              <Download className="h-4 w-4" />
              {showLabel && "Export"}
            </>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-56" align="end">
        <DropdownMenuLabel>Export Options</DropdownMenuLabel>
        <DropdownMenuSeparator />

        {/* Document export options - PDF only as per requirement */}
        <DropdownMenuItem onClick={() => handleExport('pdf', 'user')}>
          <FileText className="h-4 w-4 mr-2" />
          <span>PDF Document</span>
        </DropdownMenuItem>

        <DropdownMenuSeparator />

        {/* Comprehensive archive for all files */}
        <DropdownMenuItem onClick={() => handleExport('zip', 'user')}>
          <Package className="h-4 w-4 mr-2" />
          <span>Complete Archive (ZIP)</span>
        </DropdownMenuItem>

        {includeReportTypes && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuLabel className="text-xs text-muted-foreground">Advanced Options</DropdownMenuLabel>
            <DropdownMenuItem onClick={() => handleExport('pdf', 'admin')}>
              <PenTool className="h-4 w-4 mr-2" />
              <span>Admin Report</span>
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

