import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { RotateCcw, RotateCw, ZoomIn, ZoomOut, Download, FileText } from "lucide-react";
import { TransformWrapper, TransformComponent } from "react-zoom-pan-pinch";
import type { UploadedFile } from "@/types";

interface FilePreviewDialogProps {
  file: UploadedFile;
  onClose: () => void;
}

export function FilePreviewDialog({ file, onClose }: FilePreviewDialogProps) {
  const [rotation, setRotation] = useState(0);
  const isImage = file.fileType.startsWith('image/');
  const isPDF = file.fileType === 'application/pdf';

  const handleRotate = (direction: 'left' | 'right') => {
    setRotation(prev => {
      const newRotation = direction === 'left' ? prev - 90 : prev + 90;
      return ((newRotation % 360) + 360) % 360;
    });
  };

  const handleDownload = async () => {
    try {
      const response = await fetch(file.fileUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = file.fileName;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error('Error downloading file:', error);
    }
  };

  const renderContent = () => {
    if (isImage) {
      return (
        <TransformWrapper>
          {({ zoomIn, zoomOut }) => (
            <>
              <div className="absolute top-4 left-4 z-50 flex items-center gap-2">
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => zoomIn()}
                  className="bg-white/90 hover:bg-white"
                >
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => zoomOut()}
                  className="bg-white/90 hover:bg-white"
                >
                  <ZoomOut className="h-4 w-4" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => handleRotate('left')}
                  className="bg-white/90 hover:bg-white"
                >
                  <RotateCcw className="h-4 w-4" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  onClick={() => handleRotate('right')}
                  className="bg-white/90 hover:bg-white"
                >
                  <RotateCw className="h-4 w-4" />
                </Button>
              </div>
              <TransformComponent>
                <div
                  style={{
                    transform: `rotate(${rotation}deg)`,
                    transition: 'transform 0.3s ease',
                  }}
                  className="flex items-center justify-center"
                >
                  <img
                    src={file.fileUrl}
                    alt={file.fileName}
                    className="max-h-[70vh] w-auto object-contain"
                  />
                </div>
              </TransformComponent>
            </>
          )}
        </TransformWrapper>
      );
    }

    if (isPDF) {
      return (
        <div className="w-full h-[70vh] bg-white rounded-lg overflow-hidden">
          <embed
            src={`${file.fileUrl}#toolbar=0&navpanes=0`}
            type="application/pdf"
            width="100%"
            height="100%"
            className="w-full h-full"
          />
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center py-12">
        <FileText className="w-20 h-20 text-gray-400 mb-4" />
        <p className="text-lg font-medium text-gray-900 mb-2">{file.fileName}</p>
        <p className="text-sm text-gray-500 mb-4">
          {file.fileSize ? `${(file.fileSize / 1024 / 1024).toFixed(2)} MB` : ''}
        </p>
        <Button onClick={handleDownload}>
          <Download className="w-4 h-4 mr-2" />
          Download
        </Button>
      </div>
    );
  };

  return (
    <Dialog open={true} onOpenChange={() => onClose()}>
      <DialogContent className="max-w-4xl w-full h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center justify-between">
            <span className="truncate">{file.fileName}</span>
            <Button variant="outline" size="sm" onClick={handleDownload}>
              <Download className="w-4 h-4 mr-2" />
              Download
            </Button>
          </DialogTitle>
          <DialogDescription>
            Preview of {file.fileName}
          </DialogDescription>
        </DialogHeader>
        <div className="flex-1 relative overflow-hidden bg-gray-50 rounded-lg">
          {renderContent()}
        </div>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/FilePreviewError.t.content:
import { Button } from "@/components/ui/button";
import { AlertCircle, Download, RefreshCcw } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

interface FilePreviewErrorProps {
  error: string;
  fileType: string;
  fileName: string;
  onRetry?: () => void;
  onDownload?: () => void;
}

export function FilePreviewError({
  error,
  fileType,
  fileName,
  onRetry,
  onDownload
}: FilePreviewErrorProps) {
  const getErrorGuidance = () => {
    if (fileType === 'application/pdf') {
      return "The PDF viewer might be blocked by your browser settings. Try downloading the file or check your browser settings.";
    }
    if (fileType.startsWith('image/')) {
      return "The image might be corrupted or in an unsupported format. Try downloading the file or converting it to a different format.";
    }
    return "The file preview is not available. You can download the file to view it locally.";
  };

  return (
    <div className="p-6 bg-gray-50 rounded-lg space-y-4">
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertTitle>Preview Error</AlertTitle>
        <AlertDescription>{error}</AlertDescription>
      </Alert>

      <div className="text-sm text-gray-600">
        <p className="font-medium mb-2">Troubleshooting guidance:</p>
        <p>{getErrorGuidance()}</p>
      </div>

      <div className="flex gap-3 mt-4">
        {onRetry && (
          <Button onClick={onRetry} variant="outline">
            <RefreshCcw className="w-4 h-4 mr-2" />
            Retry Preview
          </Button>
        )}
        {onDownload && (
          <Button onClick={onDownload}>
            <Download className="w-4 h-4 mr-2" />
            Download {fileName}
          </Button>
        )}
      </div>
    </div>
  );
}

client/src/components/FileUploadMultiple.content:
import React, { useCallback, useEffect, useState, ReactNode } from 'react';
import { useToast } from '../hooks/use-toast';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Upload, Loader2, FileIcon, Eye, Download, X } from 'lucide-react';
import { cn } from '../lib/utils';
import { FileWithPreview, UploadedFile, PreviewableFile } from '../types';

export interface FileUploadMultipleProps {
  onFilesSelected: (files: File[]) => void;
  onUploadComplete?: (files: UploadedFile[]) => void;
  accept?: string;
  maxFiles?: number;
  maxSizeBytes?: number;
  isUploading?: boolean;
  uploadProgress?: number;
  previewFile?: UploadedFile | null;
  className?: string;
  children?: ReactNode;
}

export function FileUploadMultiple({
  onFilesSelected,
  onUploadComplete,
  accept = "image/*,.pdf,.doc,.docx",
  maxFiles = 5,
  maxSizeBytes = 10 * 1024 * 1024, // 10MB default
  isUploading = false,
  uploadProgress = 0,
  previewFile = null,
  className,
  children
}: FileUploadMultipleProps) {
  const [dragActive, setDragActive] = useState(false);
  const { toast } = useToast();

  // Handle drag events
  const handleDrag = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  // Triggered when files are dropped
  const handleDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files);

      // Validation
      if (files.length > maxFiles) {
        toast({
          title: "Too many files",
          description: `You can only upload up to ${maxFiles} files at a time`,
          variant: "destructive"
        });
        return;
      }

      for (const file of files) {
        if (file.size > maxSizeBytes) {
          toast({
            title: "File too large",
            description: `${file.name} exceeds the maximum size limit of ${Math.round(maxSizeBytes / (1024 * 1024))}MB`,
            variant: "destructive"
          });
          return;
        }
      }

      onFilesSelected(files);
    }
  }, [maxFiles, maxSizeBytes, onFilesSelected, toast]);

  // Handle file input change
  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const files = Array.from(e.target.files);

      // Validation
      if (files.length > maxFiles) {
        toast({
          title: "Too many files",
          description: `You can only upload up to ${maxFiles} files at a time`,
          variant: "destructive"
        });
        return;
      }

      for (const file of files) {
        if (file.size > maxSizeBytes) {
          toast({
            title: "File too large",
            description: `${file.name} exceeds the maximum size limit of ${Math.round(maxSizeBytes / (1024 * 1024))}MB`,
            variant: "destructive"
          });
          return;
        }
      }

      onFilesSelected(files);
    }
  }, [maxFiles, maxSizeBytes, onFilesSelected, toast]);

  return (
    <div 
      className={cn(
        "relative border rounded-md transition-colors",
        dragActive ? "border-primary border-dashed bg-primary/5" : "border-input",
        className
      )}
      onDragEnter={handleDrag}
      onDragOver={handleDrag}
      onDragLeave={handleDrag}
      onDrop={handleDrop}
    >
      <Input
        type="file"
        multiple={maxFiles > 1}
        accept={accept}
        onChange={handleFileChange}
        className="absolute inset-0 cursor-pointer opacity-0 w-full h-full"
        disabled={isUploading}
      />

      <div className="p-4 flex flex-col items-center justify-center">
        {children ? (
          children
        ) : (
          <>
            <div className="rounded-full bg-primary/10 p-3 mb-2">
              <Upload className="h-6 w-6 text-primary" />
            </div>
            <p className="text-sm font-medium mb-1">Drag & drop or click to upload</p>
            <p className="text-xs text-muted-foreground">
              Accepted files: {accept.split(',').join(', ')}
            </p>
            {maxFiles > 1 && (
              <p className="text-xs text-muted-foreground mt-1">
                Up to {maxFiles} files, max {Math.round(maxSizeBytes / (1024 * 1024))}MB each
              </p>
            )}
          </>
        )}
      </div>

      {isUploading && (
        <div className="absolute inset-0 bg-background/80 flex items-center justify-center">
          <div className="text-center">
            <Loader2 className="h-8 w-8 animate-spin mx-auto mb-2 text-primary" />
            <p className="text-sm">Uploading...</p>
            {uploadProgress > 0 && (
              <div className="w-48 mt-2 bg-secondary h-2 rounded-full overflow-hidden">
                <div
                  className="bg-primary h-full transition-all duration-300"
                  style={{ width: `${uploadProgress}%` }}
                />
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

