                              <Switch
                                id={`in-app-${pref.id}`}
                                checked={pref.inAppEnabled}
                                onCheckedChange={(checked) =>
                                  updatePreference({
                                    id: pref.id,
                                    data: { inAppEnabled: checked }
                                  })
                                }
