import { useState, useEffect, useCallback, useRef } from "react";
import { Bell, ExternalLink } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Skeleton } from "@/components/ui/skeleton";
import { useNotifications } from "@/hooks/use-notifications";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";

// Import Notification interface from use-notifications.ts
interface Notification {
  id: number;
  userId: number;
  title: string;
  message: string;
  type: string;
  priority?: string;
  link: string | null;
  requestId?: number;
  isRead: boolean;
  createdAt: string;
  updatedAt: string;
}

interface NotificationsDropdownProps {
  onNotificationClick: (notification: { id: number; link: string | null; requestId?: number }) => void;
}

export function NotificationsDropdown({ onNotificationClick }: NotificationsDropdownProps) {
  const [open, setOpen] = useState(false);
  const { notifications, unreadCount, highPriorityCount, isLoading, markAsRead, refetch } = useNotifications();
  const pollTimerRef = useRef<number | null>(null);

  // Optimized polling with proper error handling and cleanup
  useEffect(() => {
    const pollNotifications = async () => {
      try {
        // Only fetch if dropdown is open and not already loading
        if (open && !isLoading) {
          await refetch();
        }
      } catch (error) {
        console.error('Failed to fetch notifications:', error);
      }
    };

    // Only poll when dropdown is open
    if (open) {
      // Fetch once immediately when opened
      pollNotifications();

      // Set up polling with a longer interval (60 seconds instead of 30)
      if (!pollTimerRef.current) {
        pollTimerRef.current = window.setInterval(pollNotifications, 60000);
      }
    } else if (pollTimerRef.current) {
      // Clear polling when dropdown closes
      window.clearInterval(pollTimerRef.current);
      pollTimerRef.current = null;
    }

    // Cleanup function
    return () => {
      if (pollTimerRef.current) {
        window.clearInterval(pollTimerRef.current);
        pollTimerRef.current = null;
      }
    };
  }, [open, refetch, isLoading]);

  // Removed duplicate cleanup effect that was causing potential memory issues

  const handleNotificationClick = useCallback(async (notification: { id: number; link: string | null; requestId?: number }) => {
    try {
      // Check if the notification exists and is not read yet
      // Use proper typing with our interface
      const notificationsList = Array.isArray(notifications) ? notifications as Notification[] : [];
      const notificationToMark = notificationsList.find(n => n && n.id === notification.id);

      if (notificationToMark && !notificationToMark.isRead) {
        await markAsRead(notification.id);
      }

      setOpen(false);
      onNotificationClick({
        id: notification.id, 
        link: notification.link,
        requestId: notificationToMark?.requestId
      });
    } catch (error) {
      console.error('Error handling notification click:', error);
    }
  }, [notifications, markAsRead, onNotificationClick]);

  const getPriorityStyles = (priority: string = 'normal') => {
    switch (priority) {
      case 'high':
        return 'bg-red-500';
      case 'normal':
        return 'bg-blue-500';
      case 'low':
        return 'bg-gray-500';
      default:
        return 'bg-blue-500';
    }
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button 
          variant="outline" 
          size="icon" 
          className="relative interactive-bounce"
          aria-label={`Notifications ${unreadCount > 0 ? `(${unreadCount} unread)` : ''}`}
        >
          <Bell className={cn(
            "h-5 w-5",
            highPriorityCount > 0 && "text-red-500"
          )} />
          {unreadCount > 0 && (
            <span className={cn(
              "absolute -top-1 -right-1 h-5 w-5 rounded-full text-white text-xs flex items-center justify-center animate-fade-in",
              highPriorityCount > 0 ? "bg-red-500" : "bg-blue-500"
            )}>
              {unreadCount}
            </span>
          )}
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent align="end" className="w-[380px]">
        <div className="flex items-center justify-between px-4 py-2 border-b">
          <h4 className="font-medium">Notifications</h4>
          {unreadCount > 0 && (
            <div className="flex gap-2 items-center">
              {highPriorityCount > 0 && (
                <span className="text-sm text-red-500 font-medium">
                  {highPriorityCount} high priority
                </span>
              )}
              <span className="text-sm text-muted-foreground">
                {unreadCount} unread
              </span>
            </div>
          )}
        </div>

        <ScrollArea className="h-[400px]">
          {isLoading ? (
            <div className="space-y-4 p-4">
              {Array.from({ length: 3 }).map((_, i) => (
                <div key={i} className="flex items-start gap-4">
                  <Skeleton className="h-8 w-8 rounded-full" />
                  <div className="space-y-2 flex-1">
                    <Skeleton className="h-4 w-full" />
                    <Skeleton className="h-3 w-3/4" />
                  </div>
                </div>
              ))}
            </div>
          ) : (!Array.isArray(notifications) || notifications.length === 0) ? (
            <div className="text-center py-8 text-sm text-muted-foreground">
              No notifications
            </div>
          ) : (
            <div className="divide-y">
              {(notifications as Notification[]).map((notification) => (
                <div
                  key={notification.id}
                  className={cn(
                    "w-full text-left px-4 py-3 hover:bg-muted/50 transition-colors group relative",
                    notification.isRead === false && "bg-muted/20"
                  )}
                >
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      handleNotificationClick({
                        id: notification.id,
                        link: notification.link,
                        requestId: notification.requestId
                      });
                    }}
                    className="w-full text-left cursor-pointer focus:outline-none focus:ring-2 focus:ring-primary/20 rounded-md p-2 hover:bg-muted/50 transition-colors"
                  >
                    <div className="flex justify-between items-start gap-2">
                      <div>
                        <div className="flex items-center gap-2">
                          <p className="font-medium">{notification.title}</p>
                          {notification.priority === 'high' && (
                            <span className="px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-700">
                              High Priority
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground mt-1">{notification.message}</p>
                      </div>
                      {notification.link && (
                        <ExternalLink className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
                      )}
                    </div>
                    <p className="text-xs text-muted-foreground mt-2">
                      {notification.createdAt && formatDistanceToNow(new Date(notification.createdAt), { addSuffix: true })}
                    </p>
                  </button>
                  {notification.isRead === false && (
                    <div className={cn(
                      "absolute left-1 top-1/2 -translate-y-1/2 w-1.5 h-1.5 rounded-full",
                      getPriorityStyles(notification.priority)
                    )} />
                  )}
                </div>
              ))}
            </div>
          )}
        </ScrollArea>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

client/src/components/PDFImageUploader.t.content:
import React, { useState, useRef } from 'react';
import { useToast } from '../hooks/use-toast';
import { 
  Card, 
  CardContent,
} from './ui/card';
import { Button } from './ui/button';
import { FileUploadMultiple } from './FileUploadMultiple';
import { 
  Upload, 
  X, 
  Image as ImageIcon,
  RefreshCw,
  Trash,
} from 'lucide-react';
import axios from 'axios';

export interface PDFImageUploaderProps {
  type: 'header' | 'footer' | 'logo';
  currentImage: string | null;
  onUploadComplete: (fileUrl: string) => void;
  maxSizeInMB?: number;
}

export function PDFImageUploader({ 
  type, 
  currentImage, 
  onUploadComplete,
  maxSizeInMB = 5
}: PDFImageUploaderProps) {
  const [isUploading, setIsUploading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  // Convert MB to bytes for validation
  const maxSize = maxSizeInMB * 1024 * 1024;

  const handleFileChange = async (files: File[]) => {
    if (files.length === 0) return;

    const file = files[0]; // Take only the first file

    // Validate file type
    if (!file.type.includes('image/jpeg') && !file.type.includes('image/png')) {
      toast({
        title: 'Invalid file type',
        description: 'Please upload JPG or PNG images only',
        variant: 'destructive',
      });
      return;
    }

    // Validate file size
    if (file.size > maxSize) {
      toast({
        title: 'File too large',
        description: `Please upload images smaller than ${maxSizeInMB}MB`,
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsUploading(true);

      const formData = new FormData();
      formData.append('files', file); // Backend expects 'files' as the field name
      formData.append('type', type);

      // Use the correct endpoint from our backend
      const response = await axios.post('/api/pdf/upload-images', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        withCredentials: true, // Important for auth sessions
      });

      if (response.data && response.data.fileUrl) {
        onUploadComplete(response.data.fileUrl);
        toast({
          title: 'Upload successful',
          description: `${type.charAt(0).toUpperCase() + type.slice(1)} image uploaded successfully`,
          variant: 'default',
        });
      }
    } catch (error) {
      console.error('Upload failed:', error);
      toast({
        title: 'Upload failed',
        description: 'Failed to upload image. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setIsUploading(false);
    }
  };

  const handleRemoveImage = async () => {
    try {
      // Update settings in the database to remove the image reference
      const updateData: Record<string, any> = {};

      if (type === 'header') updateData.headerImage = null;
      if (type === 'footer') updateData.footerImage = null;
      if (type === 'logo') updateData.logo = null;

      // Save the updated settings to the database
      await axios.post('/api/pdf/settings', updateData, {
        withCredentials: true,
      });

      // Clear the image locally
      onUploadComplete('');

      toast({
        title: 'Image removed',
        description: `${type.charAt(0).toUpperCase() + type.slice(1)} image has been removed`,
        variant: 'default',
      });
    } catch (error) {
      console.error('Failed to remove image:', error);
      toast({
        title: 'Error',
        description: 'Failed to remove image. Please try again.',
        variant: 'destructive',
      });
    }
  };

  return (
    <div className="space-y-2">
      {currentImage ? (
        <div className="relative border rounded-lg overflow-hidden">
          <img 
            src={currentImage} 
            alt={`${type} image`} 
            className="w-full h-auto max-h-36 object-contain"
          />
          <div className="absolute top-2 right-2 flex space-x-1">
            <Button
              type="button"
              size="icon"
              variant="destructive"
              onClick={handleRemoveImage}
              className="h-8 w-8"
            >
              <Trash className="h-4 w-4" />
            </Button>
            <Button
              type="button"
              size="icon"
              variant="secondary"
              onClick={() => fileInputRef.current?.click()}
              className="h-8 w-8"
            >
              <RefreshCw className="h-4 w-4" />
            </Button>
          </div>
        </div>
      ) : (
        <div className="w-full p-6 border-dashed border-2 rounded-lg flex flex-col items-center justify-center text-center relative">
          <FileUploadMultiple
            onFilesSelected={handleFileChange}
            accept=".jpg,.jpeg,.png"
            maxFiles={1}
            maxSizeBytes={maxSize}
            isUploading={isUploading}
            className="absolute inset-0"
          />
          <div className="flex flex-col items-center justify-center gap-2 pointer-events-none">
            <div className="rounded-full bg-primary/10 p-2">
              <ImageIcon className="h-6 w-6 text-primary" />
            </div>
            <p className="text-sm font-medium">
              Drag & drop or click to upload
            </p>
            <p className="text-xs text-muted-foreground">
              JPG or PNG up to {maxSizeInMB}MB
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

