import { useState, useEffect, useCallback } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { type InsertVendor, vendorFormSchema } from "@db/schema";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  FormDescription
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { Star } from "lucide-react";

type VendorFormValues = InsertVendor;

interface VendorFormProps {
  onSubmit: (data: VendorFormValues) => Promise<any>;
  defaultValues?: Partial<VendorFormValues>;
}

// Simplified form component with optimized performance
export function VendorForm({ onSubmit, defaultValues }: VendorFormProps) {
  const { toast } = useToast();
  const form = useForm<VendorFormValues>({
    resolver: zodResolver(vendorFormSchema),
    defaultValues: {
      companyName: "",
      contactPerson: "",
      contactNumber: "",
      email: "",
      address: "",
      taxNumber: "",
      registrationNumber: "",
      bankName: "",
      accountNumber: "",
      ibanNumber: "",
      branchName: "",
      remarks: "",
      category: "general",
      payment_currency: "QAR",
      status: "active",
      rating: 0
    },
  });

  // Set default values when they change
  useEffect(() => {
    if (defaultValues) {
      // Process defaultValues to ensure null values are handled correctly
      const processedValues = Object.entries(defaultValues).reduce((acc, [key, value]) => {
        // Convert nulls to empty strings for the form
        acc[key] = value === null ? "" : value;
        return acc;
      }, {} as Record<string, any>);

      console.log('Setting form values with processed defaults:', processedValues);
      form.reset(processedValues);
    }
  }, [defaultValues, form]);

  // Enhanced form submission with better handling of loading states
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Direct form handler with useCallback for better performance
  const handleFormSubmit = useCallback(async (values: VendorFormValues) => {
    // Avoid excessive logging which may cause performance issues on mobile

    // Check if the form has validation errors
    if (Object.keys(form.formState.errors).length > 0) {
      toast({
        title: "Validation Error",
        description: "Please check the form for errors",
        variant: "destructive",
      });
      return;
    }

    // Prevent double submission
    if (isSubmitting) return;

    setIsSubmitting(true);

    try {
      // Process optional fields that can be null and convert types
      const processedData = { ...values };

      // Handle optional text fields
      if (processedData.taxNumber === '') processedData.taxNumber = null;
      if (processedData.registrationNumber === '') processedData.registrationNumber = null;
      if (processedData.remarks === '') processedData.remarks = null;

      // Ensure rating is properly typed as a number
      processedData.rating = typeof processedData.rating === 'string' 
        ? Number(processedData.rating) || 0
        : processedData.rating || 0;

      // For updates, make sure the ID is included
      if (defaultValues?.id) {
        processedData.id = defaultValues.id;
      }

      // Show loading toast
      const isUpdate = !!defaultValues?.id;
      toast({
        title: isUpdate ? "Updating" : "Creating",
        description: `${isUpdate ? 'Updating' : 'Creating'} vendor information...`,
      });

      // Call the parent submission handler
      const result = await onSubmit(processedData);

      // Show success toast
      toast({
        title: "Success",
        description: `Vendor ${isUpdate ? 'updated' : 'created'} successfully`,
      });

      // Only reset form for new vendor creation
      if (!isUpdate) {
        form.reset();
      }
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to save vendor",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  }, [form, toast, isSubmitting, setIsSubmitting, defaultValues, onSubmit]);

  // Use another useCallback for the button click handler
  const handleButtonClick = useCallback(() => {
    const formValues = form.getValues();
    handleFormSubmit(formValues);
  }, [form, handleFormSubmit]);

  return (
    <Form {...form}>
      <form className="space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <FormField
            control={form.control}
            name="companyName"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Company Name*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter company name" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="contactPerson"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Contact Person*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter contact person name" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="contactNumber"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Contact Number*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter contact number" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Email*</FormLabel>
                <FormControl>
                  <Input {...field} type="email" placeholder="Enter email address" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="address"
            render={({ field }) => (
              <FormItem className="col-span-1 sm:col-span-2">
                <FormLabel>Address*</FormLabel>
                <FormControl>
                  <Textarea {...field} placeholder="Enter complete address" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="taxNumber"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Tax Number</FormLabel>
                <FormControl>
                  <Input 
                    {...field} 
                    value={field.value || ''}
                    placeholder="Enter tax number (optional)" 
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="registrationNumber"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Registration Number</FormLabel>
                <FormControl>
                  <Input 
                    {...field} 
                    value={field.value || ''}
                    placeholder="Enter registration number (optional)" 
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="bankName"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Bank Name*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter bank name" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="accountNumber"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Account Number*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter account number" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="ibanNumber"
            render={({ field }) => (
              <FormItem>
                <FormLabel>IBAN Number*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter IBAN number" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="branchName"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Branch Name*</FormLabel>
                <FormControl>
                  <Input {...field} placeholder="Enter branch name" />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="rating"
            render={({ field }) => (
              <FormItem className="col-span-1 sm:col-span-2">
                <FormLabel>Vendor Rating</FormLabel>
                <FormControl>
                  <div className="flex items-center space-x-2">
                    {[1, 2, 3, 4, 5].map((rating) => (
                      <button
                        key={rating}
                        type="button"
                        className="focus:outline-none"
                        onClick={() => {
                          console.log(`Setting rating to ${rating}`);
                          field.onChange(rating);
                        }}
                      >
                        <Star
                          className={`h-5 w-5 ${
                            Number(field.value) >= rating
                              ? "fill-yellow-400 text-yellow-400"
                              : "text-gray-300"
                          }`}
                        />
                      </button>
                    ))}
                    <span className="ml-2 text-sm text-gray-600">
                      {field.value ? `${field.value}/5` : "Not rated"}
                    </span>
                  </div>
                </FormControl>
                <FormDescription>Rate this vendor from 1 to 5 stars</FormDescription>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="remarks"
            render={({ field }) => (
              <FormItem className="col-span-1 sm:col-span-2">
                <FormLabel>Remarks</FormLabel>
                <FormControl>
                  <Textarea 
                    {...field} 
                    value={field.value || ''}
                    placeholder="Enter additional remarks (optional)" 
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>

        <div className="flex justify-end gap-2">
          <Button 
            type="button" 
            disabled={isSubmitting}
            className="w-full sm:w-auto"
            onClick={handleButtonClick}
          >
            {isSubmitting ? (
              <>
                <svg className="mr-2 h-4 w-4 animate-spin" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Saving...
              </>
            ) : (
              "Save Vendor"
            )}
          </Button>
        </div>
      </form>
    </Form>
  );
}

