import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
// Fixed configuration constants - moved inline to avoid import errors
const NOTIFICATION_CONFIG = {
  MAX_RETRIES: 3,
  MIN_RETRY_DELAY: 1000,
  MAX_RETRY_DELAY: 10000,
};

const API_ROUTES = {
  NOTIFICATIONS: '/api/notifications',
  MARK_READ: (id: number) => `/api/notifications/${id}/read`,
};

const ERROR_MESSAGES = {
  UPDATE_FAILED: 'Failed to update notification',
  NOT_FOUND: 'Notification not found',
};

// Define our own notification type since importing from schema causes TS errors
interface Notification {
  id: number;
  userId: number;
  title: string;
  message: string;
  type: string;
  priority?: string;
  link: string | null;
  requestId?: number;
  isRead: boolean;
  actionType?: string;
  actionData?: {
    roleRestrictions?: string[];
    departmentRestrictions?: string[];
    [key: string]: any;
  } | null;
  isAcknowledged?: boolean;
  expiresAt?: string | null;
  createdAt: string;
  updatedAt: string;
}

interface NotificationError extends Error {
  status?: number;
  details?: any;
}

export function useNotifications() {
  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Enhanced real-time notification query with proper error handling and optimization
  const { data: notifications = [], isLoading, error } = useQuery<Notification[], NotificationError>({
    queryKey: [API_ROUTES.NOTIFICATIONS],
    retry: NOTIFICATION_CONFIG.MAX_RETRIES,
    retryDelay: (attemptIndex) => Math.min(
      NOTIFICATION_CONFIG.MIN_RETRY_DELAY * Math.pow(2, attemptIndex),
      NOTIFICATION_CONFIG.MAX_RETRY_DELAY
    ),
    // Performance optimization: Increase stale time and decrease refetch frequency
    refetchOnWindowFocus: false, // Only refetch on manual trigger or interval
    staleTime: 60000, // Consider data stale after 60 seconds instead of 5
    gcTime: 300000, // Keep in cache for 5 minutes
    refetchOnReconnect: true,
    select: (data: Notification[]) => {
      // Transform and sort notifications, prioritizing unread and high priority
      return [...data].sort((a, b) => {
        // First sort by read status
        if (!a.isRead && b.isRead) return -1;
        if (a.isRead && !b.isRead) return 1;

        // Then by priority
        const priorityOrder: Record<string, number> = { high: 0, normal: 1, low: 2 };
        const aPriority = (a.priority || 'normal') as string;
        const bPriority = (b.priority || 'normal') as string;
        const priorityDiff = (priorityOrder[aPriority] || 1) - (priorityOrder[bPriority] || 1);
        if (priorityDiff !== 0) return priorityDiff;

        // Finally by date
        return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      });
    }
  });

  const markAsRead = useMutation({
    mutationFn: async (notificationId: number) => {
      const res = await fetch(API_ROUTES.MARK_READ(notificationId), {
        method: "PUT",
        credentials: "include",
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        const error = new Error(errorData.message || ERROR_MESSAGES.UPDATE_FAILED) as NotificationError;
        error.status = res.status;
        error.details = errorData;
        throw error;
      }

      return res.json();
    },
    onSuccess: (_, notificationId) => {
      // Optimistic update
      queryClient.setQueryData<Notification[]>([API_ROUTES.NOTIFICATIONS], (oldData: Notification[] | undefined) => {
        if (!oldData) return [];
        return oldData.map((notification: Notification) => 
          notification.id === notificationId 
            ? { ...notification, isRead: true }
            : notification
        );
      });

      // Then refetch to ensure consistency
      queryClient.invalidateQueries({ queryKey: [API_ROUTES.NOTIFICATIONS] });
    },
    onError: (error: NotificationError) => {
      console.error("Failed to mark notification as read:", error);
      toast({
        title: "Error",
        description: error.status === 404 
          ? ERROR_MESSAGES.NOT_FOUND
          : ERROR_MESSAGES.UPDATE_FAILED,
        variant: "destructive",
      });
    },
    retry: NOTIFICATION_CONFIG.MAX_RETRIES
  });

  // Safely calculate unread and high priority counts to avoid type errors
  const notificationArray = Array.isArray(notifications) ? notifications : [];
  const unreadCount = notificationArray.filter((n: Notification) => !n.isRead).length;
  const highPriorityCount = notificationArray.filter((n: Notification) => !n.isRead && n.priority === 'high').length;

  return {
    notifications,
    unreadCount,
    highPriorityCount,
    isLoading,
    error,
    markAsRead: markAsRead.mutate,
    refetch: () => queryClient.invalidateQueries({ queryKey: [API_ROUTES.NOTIFICATIONS] })
  };
}

client/src/hooks/use-purchase-requests.t.content:
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToastContext } from "@/contexts/ToastContext";
import type { PurchaseRequest } from "@db/schema";
import { useErrorHandler } from "@/services/error-logging";
import { NOTIFICATION_CONFIG } from "@/config/notification";
import { useEffect, useCallback, useRef, useState } from "react";

interface ApprovalData {
  requestId: number;
  status: 'approved' | 'rejected' | 'changes_requested';
  comments?: string;
  departmentId: string;
}

export function usePurchaseRequests() {
  const { showToast } = useToastContext();
  const queryClient = useQueryClient();
  const handleError = useErrorHandler();
  const toastTimeoutRef = useRef<NodeJS.Timeout>();
  const [processedRequests] = useState(() => new Set<string>());

  // Required departments for approval
  const requiredDepartments = ['CEO Office', 'Finance', 'Director'];

  // Helper function to determine if all other departments except the given one have approved
  const allOtherDepartmentsApproved = useCallback((request: any, excludeDepartment: string) => {
    const otherDepartments = requiredDepartments.filter(dept => dept !== excludeDepartment);
    return otherDepartments.every(dept =>
      request.approvals?.some((approval: any) =>
        approval.department === dept && approval.status === 'approved'
      )
    );
  }, []);

  // Helper function to determine effective status
  const getEffectiveStatus = useCallback((request: any) => {
    if (!request.approvals) return request.status;

    const allDepartmentsApproved = requiredDepartments.every(dept =>
      request.approvals?.some((approval: any) =>
        approval.department === dept && approval.status === 'approved'
      )
    );

    return allDepartmentsApproved ? 'approved' : request.status;
  }, []);

  // Fetch all requests
  const { data: rawRequests = [], isLoading, error, refetch } = useQuery({
    queryKey: ["/api/requests"],
    queryFn: async () => {
      try {
        console.log("Fetching all requests");
        const response = await fetch("/api/requests", {
          credentials: 'include'
        });
        if (!response.ok) {
          throw new Error(`Failed to fetch requests: ${response.status}`);
        }
        const data = await response.json();
        console.log("Fetched requests:", data);
        return data;
      } catch (error) {
        console.error("Error fetching requests:", error);
        handleError(error, {
          title: 'Error Fetching Requests',
          silent: false
        });
        throw error;
      }
    },
    staleTime: NOTIFICATION_CONFIG.STALE_TIME,
    gcTime: NOTIFICATION_CONFIG.CACHE_TIME,
    retry: NOTIFICATION_CONFIG.MAX_RETRIES,
    refetchOnWindowFocus: NOTIFICATION_CONFIG.REFRESH_ON_FOCUS
  });

  // Approval mutation
  const approvalMutation = useMutation<{ message: string }, Error, ApprovalData>({
    mutationFn: async (data) => {
      const requestBody = {
        status: data.status,
        department: data.departmentId,
        comments: data.comments?.trim() || undefined,
        isAutoApproval: data.comments?.includes('Auto-approved') || false
      };

      const response = await fetch(`/api/requests/${data.requestId}/approvals`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
        credentials: 'include'
      });

      if (!response.ok) {
        throw new Error(`Failed to process approval: ${response.status}`);
      }

      return response.json();
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["/api/requests"] });

      const isAutoApproval = variables.comments?.includes('Auto-approved');
      showToast({
        title: isAutoApproval ? "Auto-Approval Completed" : "Success",
        description: isAutoApproval
          ? `Request automatically approved for ${variables.departmentId}`
          : "Approval submitted successfully",
        variant: "default", // Changed from success to default
        duration: 3000
      });
    },
    onError: (error) => {
      showToast({
        title: "Error",
        description: error.message || "Failed to process approval",
        variant: "destructive",
        duration: 7000
      });
    }
  });

  // Process auto-approvals
  const processAutoApprovals = useCallback((requests: any[]) => {
    requests.forEach((request: any) => {
      if (!request.requester?.department || !request.approvals) return;

      const requesterDepartment = request.requester.department;
      if (!requiredDepartments.includes(requesterDepartment)) return;

      // Create a unique key for this auto-approval
      const autoApprovalKey = `${request.id}-${requesterDepartment}`;

      // Skip if we've already processed this request
      if (processedRequests.has(autoApprovalKey)) return;

      // Check if conditions are met for auto-approval
      if (
        !request.approvals.some((a: any) => a.department === requesterDepartment) &&
        allOtherDepartmentsApproved(request, requesterDepartment)
      ) {
        processedRequests.add(autoApprovalKey);

        approvalMutation.mutate({
          requestId: request.id,
          status: 'approved',
          departmentId: requesterDepartment,
          comments: `Auto-approved as all other departments have approved - ${new Date().toISOString()}`
        });
      }
    });
  }, [approvalMutation, allOtherDepartmentsApproved, processedRequests]);

  // Effect to handle auto-approvals
  useEffect(() => {
    if (rawRequests?.length) {
      processAutoApprovals(rawRequests);
    }
  }, [rawRequests, processAutoApprovals]); // Proper dependency array

  return {
    requests: rawRequests.map((request: any) => ({
      ...request,
      status: getEffectiveStatus(request),
      // Ensure additionalApprovers is always an array
      additionalApprovers: Array.isArray(request.additionalApprovers) ? request.additionalApprovers : []
    })),
    isLoading,
    error,
    processApproval: approvalMutation.mutateAsync,
    refetch, // Expose the refetch function from useQuery
  };
}

client/src/hooks/use-request.ts.content:
import { useQuery } from "@tanstack/react-query";
import type { PurchaseRequestWithRelations } from "@db/schema";
import { useToast } from "./use-toast";
import { useLocation } from "wouter";

export function useRequest(id: number) {
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  return useQuery<PurchaseRequestWithRelations>({
    queryKey: [`/api/requests/${id}`],
    enabled: !!id && !isNaN(id),
    gcTime: 10 * 60 * 1000, // Keep in cache for 10 minutes
    staleTime: 5 * 60 * 1000, // Consider data fresh for 5 minutes
    refetchOnWindowFocus: false,
    refetchOnMount: true,
    retry: 1, // Reduced retries since permission errors won't resolve with retries
    queryFn: async () => {
      try {
        console.log(`Fetching single request with ID: ${id}`);
        const response = await fetch(`/api/requests/${id}`, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
          credentials: 'include'
        });

        // Handle permission errors specifically
        if (response.status === 403) {
          console.error(`Permission error fetching request: ${id}`);
          toast({
            title: "Access Denied",
            description: "You don't have permission to view this request.",
            variant: "destructive"
          });
          // Navigate back to dashboard on permission errors
          setLocation("/dashboard");
          throw new Error("You don't have permission to view this request");
        }

        // Handle other errors
        if (!response.ok) {
          console.error(`Error fetching request: ${response.status} ${response.statusText}`);
          toast({
            title: "Error",
            description: `Failed to fetch request: ${response.status === 500 ? "Internal server error" : response.statusText}`,
            variant: "destructive"
          });
          throw new Error(`Failed to fetch request: ${response.status} ${response.statusText}`);
        }

        const data = await response.json();
        console.log("Single request data:", data);
        return data;
      } catch (error) {
        console.error("Error in useRequest hook:", error);
        throw error;
      }
    }
  });
}

