      });

      // @ts-ignore - jsPDF-AutoTable adds this method
      autoTable(doc, {
        head: tableHead,
        body: tableBody,
        startY: currentY,
        margin: { left: marginLeft, right: marginRight },
        theme: 'grid',
        styles: { 
          fontSize: fontSize - 1, 
          cellPadding: 2,
          font: fontFamily,
          textColor: textColor
        },
        headStyles: { 
          fillColor: tableHeaderColor,
          textColor: [0, 0, 0], 
          fontStyle: 'bold',
          font: fontFamily
        },
        columnStyles: {
          0: { cellWidth: 30 },
