import { useState } from "react";
import { useLocation } from "wouter";
import UserManagement from "@/components/UserManagement";
import VendorManagement from "@/pages/VendorManagement";
import DepartmentDashboard from "@/pages/DepartmentDashboard";
import { SimplePDFSettings } from "@/components/SimplePDFSettings";
import TestExportPage from "@/pages/TestExportPage";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  ArrowLeft, 
  Check, 
  X, 
  Plus, 
  BarChart, 
  Users, 
  ClipboardList, 
  Building2, 
  ListTree,
  Pencil,
  Trash2,
  Loader2,
  FileText,
  Settings,
  Wrench,
  ActivitySquare
} from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { useIsMobile } from "@/hooks/use-mobile";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { AccountRequest, SubPurpose } from "@db/schema";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { insertSubPurposeSchema } from "@db/schema";
import { z } from "zod";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

export default function AdminPanel() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedTab, setSelectedTab] = useState("users");
  const [isSubPurposeDialogOpen, setIsSubPurposeDialogOpen] = useState(false);
  const [selectedSubPurpose, setSelectedSubPurpose] = useState<SubPurpose | null>(null);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const isMobile = useIsMobile();
  const [pdfSettings, setPdfSettings] = useState<Record<string, any>>({});

  // Fetch PDF settings
  const { data: pdfSettingsData } = useQuery({
    queryKey: ["/api/pdf/print-settings"],
    queryFn: async () => {
      const response = await fetch("/api/pdf/print-settings", {
        credentials: "include"
      });
      if (!response.ok) throw new Error("Failed to fetch PDF settings");
      const data = await response.json();
      // Set the settings directly after fetching
      setPdfSettings(data);
      return data;
    }
  });

  // Save PDF settings mutation
  const savePdfSettings = useMutation<
    Record<string, any>, // Return type 
    Error,              // Error type
    Record<string, any>  // Variables type
  >({
    mutationFn: async (settings: Record<string, any>) => {
      const res = await fetch("/api/pdf/settings", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(settings),
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Success",
        description: "PDF settings updated successfully",
      });
      // Update the settings with the response from the server
      setPdfSettings(data);
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Handle PDF settings changes and maintain state
  const handlePdfSettingsChange = (newSettings: Record<string, any>) => {
    // Update the local state immediately for a responsive UI
    setPdfSettings(prevSettings => {
      const mergedSettings = { ...prevSettings, ...newSettings };
      console.log('PDF settings updated:', mergedSettings);

      // Save settings to the server in the background
      savePdfSettings.mutate(mergedSettings);

      return mergedSettings;
    });
  };

  // Fetch account requests
  const { data: accountRequests = [], isLoading: isLoadingRequests } = useQuery({
    queryKey: ["/api/admin/account-requests"],
    queryFn: async () => {
      const response = await fetch("/api/admin/account-requests", {
        credentials: 'include'
      });

      if (!response.ok) throw new Error('Failed to fetch account requests');
      return response.json() as Promise<AccountRequest[]>;
    },
  });

  // Account request management
  const approveAccountRequest = useMutation({
    mutationFn: async (id: number) => {
      const res = await fetch(`/api/admin/account-requests/${id}/approve`, {
        method: "POST",
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/account-requests"] });
      toast({
        title: "Success",
        description: "Account request approved successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const rejectAccountRequest = useMutation({
    mutationFn: async (id: number) => {
      const res = await fetch(`/api/admin/account-requests/${id}/reject`, {
        method: "POST",
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/account-requests"] });
      toast({
        title: "Success",
        description: "Account request rejected successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Update role mutation
  const updateRoleMutation = useMutation({
    mutationFn: async ({ userId, role }: { userId: number; role: string }) => {
      const res = await fetch(`/api/admin/users/${userId}/update-role`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ role }),
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/account-requests"] });
      toast({
        title: "Success",
        description: "User role updated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Form for creating sub-purpose
  const form = useForm<z.infer<typeof insertSubPurposeSchema>>({
    resolver: zodResolver(insertSubPurposeSchema),
    defaultValues: {
      name: "",
      purpose_type: "E3 EVENT",
      is_frozen: false,
      valid_from: undefined,
      valid_to: undefined,
    },
  });

  // Handle form submission
  const handleSubmit = form.handleSubmit((data) => {
    const formattedData = {
      ...data,
      valid_from: data.valid_from ? new Date(data.valid_from).toISOString() : null,
      valid_to: data.valid_to ? new Date(data.valid_to).toISOString() : null,
    };
    createSubPurpose.mutate(formattedData as z.infer<typeof insertSubPurposeSchema>);
  });

  // Create sub-purpose mutation
  const createSubPurpose = useMutation({
    mutationFn: async (data: z.infer<typeof insertSubPurposeSchema>) => {
      const res = await fetch("/api/admin/sub-purposes", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sub-purposes"] });
      setIsSubPurposeDialogOpen(false);
      form.reset();
      toast({
        title: "Success",
        description: "Sub-purpose created successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Add these mutations after the createSubPurpose mutation
  const editSubPurpose = useMutation({
    mutationFn: async (data: SubPurpose) => {
      const res = await fetch(`/api/admin/sub-purposes/${data.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sub-purposes"] });
      setIsEditDialogOpen(false);
      setSelectedSubPurpose(null);
      form.reset();
      toast({
        title: "Success",
        description: "Sub-purpose updated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const deleteSubPurpose = useMutation({
    mutationFn: async (id: number) => {
      const res = await fetch(`/api/admin/sub-purposes/${id}`, {
        method: "DELETE",
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sub-purposes"] });
      setIsDeleteDialogOpen(false);
      setSelectedSubPurpose(null);
      toast({
        title: "Success",
        description: "Sub-purpose deleted successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Fetch sub-purposes
  const { data: subPurposes = [], isLoading: isLoadingSubPurposes } = useQuery<SubPurpose[]>({
    queryKey: ["/api/admin/sub-purposes"],
    queryFn: async () => {
      const response = await fetch("/api/admin/sub-purposes", {
        credentials: "include",
      });
      if (!response.ok) throw new Error("Failed to fetch sub-purposes");
      return response.json();
    },
  });

  const toggleSubPurposeFreeze = useMutation({
    mutationFn: async ({ id, isFrozen }: { id: number; isFrozen: boolean }) => {
      const res = await fetch(`/api/admin/sub-purposes/${id}/freeze`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ isFrozen }),
        credentials: "include",
      });

      if (!res.ok) {
        throw new Error(await res.text());
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/sub-purposes"] });
      toast({
        title: "Success",
        description: "Sub-purpose status updated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Handle edit click
  const handleEditClick = (subPurpose: SubPurpose) => {
    setSelectedSubPurpose(subPurpose);
    form.reset({
      name: subPurpose.name,
      purpose_type: subPurpose.purpose_type,
      valid_from: subPurpose.valid_from ? new Date(subPurpose.valid_from).toISOString().slice(0, 16) : undefined,
      valid_to: subPurpose.valid_to ? new Date(subPurpose.valid_to).toISOString().slice(0, 16) : undefined,
      is_frozen: subPurpose.is_frozen,
    });
    setIsEditDialogOpen(true);
  };

  // Handle delete click
  const handleDeleteClick = (subPurpose: SubPurpose) => {
    setSelectedSubPurpose(subPurpose);
    setIsDeleteDialogOpen(true);
  };

  // Handle edit submit
  const handleEditSubmit = form.handleSubmit((data) => {
    if (!selectedSubPurpose) return;

    const formattedData = {
      ...data,
      id: selectedSubPurpose.id,
      valid_from: data.valid_from ? new Date(data.valid_from).toISOString() : null,
      valid_to: data.valid_to ? new Date(data.valid_to).toISOString() : null,
    };
    editSubPurpose.mutate(formattedData as SubPurpose);
  });

  return (
    <div className="container mx-auto py-8">
      <Button
        variant="ghost"
        className="mb-4 hover:bg-[#7156a2]/10 transition-colors interactive-bounce"
        onClick={() => setLocation("/")}
      >
        <ArrowLeft className="h-4 w-4 mr-2" />
        Back to Dashboard
      </Button>

      <Tabs value={selectedTab} onValueChange={setSelectedTab}>
        <TabsList className="grid w-full grid-cols-7">
          <TabsTrigger value="users">
            {isMobile ? (
              <Users className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <Users className="h-4 w-4 mr-2" />
                <span>Users</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="requests">
            {isMobile ? (
              <ClipboardList className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <ClipboardList className="h-4 w-4 mr-2" />
                <span>Requests</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="vendors">
            {isMobile ? (
              <Building2 className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <Building2 className="h-4 w-4 mr-2" />
                <span>Vendors</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="sub-purposes">
            {isMobile ? (
              <ListTree className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <ListTree className="h-4 w-4 mr-2" />
                <span>Sub-purposes</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="pdf-settings">
            {isMobile ? (
              <FileText className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <FileText className="h-4 w-4 mr-2" />
                <span>PDF Settings</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="diagnostics">
            {isMobile ? (
              <ActivitySquare className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <ActivitySquare className="h-4 w-4 mr-2" />
                <span>Diagnostics</span>
              </div>
            )}
          </TabsTrigger>
          <TabsTrigger value="department-analytics">
            {isMobile ? (
              <BarChart className="h-5 w-5" />
            ) : (
              <div className="flex items-center">
                <BarChart className="h-4 w-4 mr-2" />
                <span>Analytics</span>
              </div>
            )}
          </TabsTrigger>

        </TabsList>

        {/* Account Requests Tab */}
        <TabsContent value="requests">
          <Card>
            <CardHeader>
              <CardTitle>Account Requests</CardTitle>
              <CardDescription>
                Manage pending account creation requests
              </CardDescription>
            </CardHeader>
            <CardContent>
              {isLoadingRequests ? (
                <div className="flex justify-center py-8">
                  <Loader2 className="h-8 w-8 animate-spin" />
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Username</TableHead>
                      <TableHead>Email</TableHead>
                      <TableHead>Department</TableHead>
                      <TableHead>Role</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {accountRequests.map((request) => (
                      <TableRow key={request.id}>
                        <TableCell>{request.username}</TableCell>
                        <TableCell>{request.email}</TableCell>
                        <TableCell>{request.department}</TableCell>
                        <TableCell>
                          {request.status === "pending" ? (
                            <Select
                              value={request.role}
                              onValueChange={(value) => {
                                updateRoleMutation.mutate({
                                  userId: request.id,
                                  role: value,
                                });
                              }}
                            >
                              <SelectTrigger className="w-[120px]">
                                <SelectValue placeholder="Select role" />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="user">User</SelectItem>
                                <SelectItem value="approver">Approver</SelectItem>
                                <SelectItem value="admin">Admin</SelectItem>
                              </SelectContent>
                            </Select>
                          ) : (
                            <Badge
                              className={cn(
                                "bg-slate-100 text-slate-800",
                                {
                                  "bg-blue-100 text-blue-800": request.role === "admin",
                                  "bg-purple-100 text-purple-800": request.role === "approver",
                                  "bg-green-100 text-green-800": request.role === "user",
                                }
                              )}
                            >
                              {request.role}
                            </Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <Badge
                            className={cn(
                              request.status === "pending"
                                ? "bg-yellow-100 text-yellow-800"
                                : request.status === "approved"
                                  ? "bg-green-100 text-green-800"
                                  : "bg-red-100 text-red-800"
                            )}
                          >
                            {request.status}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          {request.status === "pending" && (
                            <div className="flex gap-2">
                              <Button
                                variant="ghost"
                                size="icon"
                                className="text-green-500 hover:text-green-700"
                                onClick={() => approveAccountRequest.mutate(request.id)}
                                disabled={approveAccountRequest.isPending}
                              >
                                {approveAccountRequest.isPending ? (
                                  <Loader2 className="h-4 w-4 animate-spin" />
                                ) : (
                                  <Check className="h-4 w-4" />
                                )}
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="text-red-500 hover:text-red-700"
                                onClick={() => rejectAccountRequest.mutate(request.id)}
                                disabled={rejectAccountRequest.isPending}
                              >
                                {rejectAccountRequest.isPending ? (
                                  <Loader2 className="h-4 w-4 animate-spin" />
                                ) : (
                                  <X className="h-4 w-4" />
                                )}
                              </Button>
                            </div>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* User Management Tab */}
        <TabsContent value="users">
          <Card>
            <CardHeader>
              <CardTitle>User Management</CardTitle>
              <CardDescription>
                Manage user accounts, roles, and access
              </CardDescription>
            </CardHeader>
            <CardContent>
              <UserManagement />
            </CardContent>
          </Card>
        </TabsContent>

        {/* Vendor Management Tab */}
        <TabsContent value="vendors">
          <Card>
            <CardHeader>
              <CardTitle>Vendor Management</CardTitle>
              <CardDescription>
                Manage vendor accounts, status, and information
              </CardDescription>
            </CardHeader>
            <CardContent>
              <VendorManagement />
            </CardContent>
          </Card>
        </TabsContent>

        {/* Sub-purposes Tab */}
        <TabsContent value="sub-purposes">
          <Card>
            <CardHeader>
              <CardTitle>Sub-purposes Management</CardTitle>
              <CardDescription>
                Manage sub-purposes for purchase requests
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="mb-4">
                <Button
                  onClick={() => setIsSubPurposeDialogOpen(true)}
