                </TabsContent>
                <TabsContent value="changes">
                  {renderRequestsTable(categorizedRequests.changes)}
                </TabsContent>
              </>
            )}
            {!isAdmin && !isSpecialRole && showApprovalsTab && (
              <TabsContent value="approvals">
                {renderRequestsTable(categorizedRequests.approvals, true)}
              </TabsContent>
            )}
          </div>
        </Tabs>
      </main>
    </div>
  );
}

