import { useState, useEffect, useMemo, useCallback } from "react";
import { useLocation, useParams } from "wouter";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useRequest } from "@/hooks/use-request";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, ArrowLeft, Plus, Trash } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  insertPurchaseRequestSchema,
  type PurchaseRequest,
  type Vendor
} from "@db/schema";
import { updateRequest, saveDraft, submitRequest } from "@/services/requests";
import { analyzeValidationContext, analyzeDraftSubmission } from "@/services/anthropicService";
import DepartmentSelect from "@/components/DepartmentSelect";
import SubPurposeSelect from "@/components/SubPurposeSelect";
import VendorSelect from "@/components/VendorSelect";

// Helper function to parse and format decimal numbers with strict validation
const formatDecimal = (value: number | string): number => {
  const parsed = typeof value === 'string' ? parseFloat(value) : value;
  if (isNaN(parsed)) return 0;
  return Number(parsed.toFixed(2));
};

interface RequestItem {
  name: string;
  quantity: number;
  estimatedCost: number;
  description: string;
}

const currencies = [
  { label: "QAR", value: "QAR" },
  { label: "USD", value: "USD" },
  { label: "CNY", value: "CNY" },
] as const;

const priorities = [
  { label: "Low", value: "low" },
  { label: "Medium", value: "medium" },
  { label: "High", value: "high" },
  { label: "Urgent", value: "urgent" },
] as const;

export default function EditRequest({ params }: { params: { id: string } }) {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [items, setItems] = useState<RequestItem[]>([]);
  const [freightAmount, setFreightAmount] = useState<number>(0);
  const [selectedVendor, setSelectedVendor] = useState<number | undefined>(undefined);

  const { data: request, isLoading } = useRequest(parseInt(params.id));

  // Memoize form configuration
  const defaultValues = useMemo(() => ({
    title: "",
    description: "",
    items: [],
    purposeType: "E3 EVENT",
    subPurposeId: undefined,
    priority: "medium",
    currency: "QAR",
    status: "draft",
    totalEstimatedCost: 0,
    freightAmount: 0,
  }), []);

  const form = useForm<PurchaseRequest>({
    resolver: zodResolver(insertPurchaseRequestSchema),
    defaultValues,
  });

  // Memoize decimal input validation
  const validateDecimalInput = useMemo(() => (value: string): boolean => {
    return /^\d*\.?\d{0,2}$/.test(value);
  }, []);

  useEffect(() => {
    if (request) {
      const formattedItems = request.items?.map(item => ({
        name: item.name || "",
        quantity: formatDecimal(item.quantity || 0),
        estimatedCost: formatDecimal(item.estimatedCost || 0),
        description: item.description || ""
      })) || [];

      if (formattedItems.length === 0) {
        formattedItems.push({ 
          name: "", 
          quantity: 1, 
          estimatedCost: 0, 
          description: "" 
        });
      }

      setItems(formattedItems);
      setFreightAmount(formatDecimal(request.freightAmount || 0));

      // Set the vendor ID from the request
      if (request.vendorId) {
        setSelectedVendor(request.vendorId);
      }

      form.reset({
        ...request,
        items: formattedItems,
        totalEstimatedCost: formatDecimal(request.totalEstimatedCost || 0),
        freightAmount: formatDecimal(request.freightAmount || 0),
      });
    }
  }, [request, form]);

  // Memoize the total cost calculation
  const totalCost = useMemo(() => {
    const itemsTotal = items.reduce(
      (sum, item) => sum + (formatDecimal(item.quantity) * formatDecimal(item.estimatedCost)),
      0
    );
    return formatDecimal(itemsTotal + formatDecimal(freightAmount));
  }, [items, freightAmount]);

  // Memoize item update handler
  const updateItem = useCallback((index: number, field: string, value: string | number) => {
    if ((field === 'quantity' || field === 'estimatedCost') && 
        typeof value === 'string' && 
        !validateDecimalInput(value)) {
      return;
    }

    setItems(prevItems => {
      const newItems = [...prevItems];
      newItems[index] = {
        ...newItems[index],
        [field]: field === "name" || field === "description" 
          ? value 
          : formatDecimal(value),
      };
      return newItems;
    });
  }, [validateDecimalInput]);

  const addItem = useCallback(() => {
    setItems(prev => [...prev, { name: "", quantity: 1, estimatedCost: 0, description: "" }]);
  }, []);

  const removeItem = useCallback((index: number) => {
    setItems(prev => {
      // Only remove if we have more than one item
      if (prev.length > 1) {
        const newItems = prev.filter((_, i) => i !== index);
        // Update form value with the new items array
        form.setValue('items', newItems);
        return newItems;
      }
      return prev;
    });
  }, [form]);

  const handleVendorCreated = useCallback((vendor: Vendor) => {
    setSelectedVendor(vendor.id);
  }, []);

  // Memoize submit handler
  const onSubmit = useCallback(async (values: PurchaseRequest) => {
    try {
      // Different validation based on status
      const isDraft = values.status === "draft";

      if (values.status === "pending") {
        // Validate required fields for final submission
        const validationErrors = [];

        if (!values.title?.trim()) {
          validationErrors.push("Please provide a title");
        }

        if (!values.description?.trim() || values.description.length < 10) {
          validationErrors.push("Description must be at least 10 characters");
        }

        if (!values.purposeType) {
          validationErrors.push("Please select a purpose type");
        }

        // Require sub-purpose only for PROJECT type
        if (values.purposeType === 'PROJECT' && !values.subPurposeId) {
          validationErrors.push("Please select a sub-purpose for PROJECT type");
        }

        if (!selectedVendor) {
          validationErrors.push("Please select a vendor");
        }

        if (items.length === 0) {
          validationErrors.push("Please add at least one item");
        } else {
          // Check each item for validation
          items.forEach((item, index) => {
            if (!item.name || !item.name.trim()) {
              validationErrors.push(`Item ${index + 1} name is required`);
            }
            if (!item.quantity || item.quantity <= 0) {
              validationErrors.push(`Item ${index + 1} quantity must be greater than 0`);
            }
            if (typeof item.estimatedCost !== 'number' || item.estimatedCost <= 0) {
              validationErrors.push(`Item ${index + 1} estimated cost must be greater than 0`);
            }
          });
        }

        // Display all validation errors
        if (validationErrors.length > 0) {
          // Display first error as toast
          toast({
            title: "Validation Error",
            description: validationErrors[0],
            variant: "destructive",
          });

          // If there are more errors, log them to console
          if (validationErrors.length > 1) {
            console.error("Additional validation errors:", validationErrors.slice(1));
          }
          return;
        }
      } else if (values.status === "draft") {
        // For drafts, minimal validation - just ensure quantities are valid if names are provided
        if (items.length > 0 && items.some(item => item.name && item.quantity <= 0)) {
          toast({
            title: "Validation Warning",
            description: "Items with a name should have a quantity greater than 0",
            variant: "default"
          });
          // Allow to continue for drafts
        }

        // No other validations for drafts - we allow incomplete data
        console.log("Saving as draft - minimal validation applied");
      }

      // Special handling for draft requests to ensure data is correctly formatted
      // even if it's incomplete
      const formattedItems = items.map(item => ({
        name: item.name || "",
        quantity: formatDecimal(item.quantity || 0),
        estimatedCost: formatDecimal(item.estimatedCost || 0),
        description: item.description || ""
      }));

      const submissionData = {
        ...values,
        items: formattedItems,
        freightAmount: formatDecimal(freightAmount || 0),
        totalEstimatedCost: totalCost,
        // For drafts, we allow null values for optional fields
        vendorId: isDraft ? (selectedVendor || null) : selectedVendor,
        updatedAt: new Date().toISOString()
      };

      console.log("Submitting request data:", {
        isDraft,
        status: values.status,
        itemCount: formattedItems.length,
        vendorId: submissionData.vendorId
      });

      // Use specific service functions based on the request status
      if (isDraft) {
        await saveDraft(parseInt(params.id), submissionData);
      } else {
        await submitRequest(parseInt(params.id), submissionData);
      }

      toast({
        title: "Success",
        description: "Request updated successfully",
        className: "animate-success",
      });

      setLocation("/");
    } catch (error: any) {
      console.error("Update error:", error);
      toast({
        title: "Error",
        description: error.message || "Failed to update request",
        variant: "destructive",
        className: "animate-error",
      });
    }
  // Removed totalCost from dependency array to prevent circular dependency
  }, [items, freightAmount, selectedVendor, params.id, setLocation, toast]);

  const handleSubmit = useCallback(async (status: "draft" | "pending") => {
    try {
      // For drafts, we'll be more lenient with validation
      if (status === "draft") {
        // For drafts, we only need the basic information
        const currentValues = form.getValues();

        console.log("Saving as draft with minimal validation", {
          items,
          title: currentValues.title,
          description: currentValues.description,
          status: "draft"
        });

        // Safely calculate total cost to avoid NaN errors
        const calculatedTotalCost = items.reduce(
          (acc, item) => acc + (Number(item.quantity || 0) * Number(item.estimatedCost || 0)), 
          0
        ) + Number(freightAmount || 0);

        // Prepare data for draft submission with special handling for empty or partial data
        const draftData = {
          ...currentValues,
          items: items.map(item => ({
            name: item.name || "",
            // Ensure numeric values are properly formatted
            quantity: item.quantity != null && !isNaN(Number(item.quantity)) 
              ? Number(item.quantity) 
              : 0,
            estimatedCost: item.estimatedCost != null && !isNaN(Number(item.estimatedCost)) 
              ? Number(item.estimatedCost) 
              : 0,
            description: item.description || ""
          })),
          status: "draft",
          // For drafts, accept null values for all optional fields
          vendorId: selectedVendor || null,
          totalEstimatedCost: calculatedTotalCost,
          freightAmount: freightAmount != null && !isNaN(Number(freightAmount)) 
            ? Number(freightAmount) 
            : 0,
          updatedAt: new Date().toISOString()
        };

        try {
          // Use AI to analyze and potentially enhance the draft before saving
          if (import.meta.env.VITE_ANTHROPIC_API_KEY) {
            try {
              // Only attempt AI enhancement if there's data to work with
              if (draftData.title || draftData.description || draftData.items.some(i => i.name)) {
                const result = await analyzeDraftSubmission(
                  draftData,
                  [] // No validation errors for drafts
                );

                if (result.fixedData) {
                  console.log("AI enhanced draft data:", result.analysisMessage);
                  // Keep status as draft and use the enhanced data
                  const enhancedData = {
                    ...result.fixedData,
                    status: "draft" // Ensure status remains draft
                  };

                  await saveDraft(parseInt(params.id), enhancedData);

                  toast({
                    title: "Draft Enhanced & Saved",
                    description: result.analysisMessage || "Draft saved with AI-suggested improvements",
                    variant: "default",
                  });

                  setLocation("/");
                  return;
                }
              }
            } catch (aiError) {
              // If AI enhancement fails, continue with normal draft saving
              console.warn("AI draft enhancement failed, continuing with basic save:", aiError);
            }
          }

          // Standard draft saving if AI enhancement wasn't used or failed
          await saveDraft(
            parseInt(params.id),
            draftData
          );

          toast({
            title: "Success",
            description: "Draft saved successfully",
            variant: "default",
          });

          setLocation("/");
        } catch (error: any) {
          console.error("Draft save error:", error);
          toast({
            title: "Error",
            description: error.message || "Failed to save draft",
            variant: "destructive",
          });
        }
        return;
      }

      // For pending/submission, we need comprehensive validation
      // First trigger form validation
      const isValid = await form.trigger();

      // Perform custom validation checks
      const validationErrors = [];
      const currentValues = form.getValues();

      // Required field validation
      if (!currentValues.title?.trim()) {
        validationErrors.push("Title is required");
      }

      if (!currentValues.description?.trim() || currentValues.description.length < 10) {
        validationErrors.push("Description must be at least 10 characters");
      }

      if (!currentValues.purposeType) {
        validationErrors.push("Purpose type is required");
      }

      // Only require subPurposeId for PROJECT type, or if already provided
      if (currentValues.purposeType === 'PROJECT' && !currentValues.subPurposeId) {
        validationErrors.push("Sub-purpose is required for PROJECT type");
      }

      if (!selectedVendor) {
        validationErrors.push("Vendor selection is required");
      }

      // Items validation
      if (items.length === 0) {
        validationErrors.push("Please add at least one item");
      } else {
        items.forEach((item, index) => {
          if (!item.name || !item.name.trim()) {
            validationErrors.push(`Item ${index + 1} name is required`);
          }
          if (!item.quantity || item.quantity <= 0) {
            validationErrors.push(`Item ${index + 1} quantity must be greater than 0`);
          }
          if (typeof item.estimatedCost !== 'number' || item.estimatedCost <= 0) {
            validationErrors.push(`Item ${index + 1} estimated cost must be greater than 0`);
          }
        });
      }

      if (!isValid || validationErrors.length > 0) {
        console.log("Validation errors detected, checking with AI assistant...");

        // Prepare data for AI analysis
        const formData = {
          ...currentValues,
          items,
          freightAmount,
          totalEstimatedCost: totalCost,
          vendorId: selectedVendor || null,
          updatedAt: new Date().toISOString()
        };

        try {
          // Use Anthropic Claude to analyze the validation context and decide if we can proceed
          const aiAnalysis = await analyzeValidationContext(
            formData,
            validationErrors,
            'submit'
          );

          if (aiAnalysis.shouldProceed) {
            // AI suggests proceeding despite validation errors
            console.log("AI recommends proceeding with fixed data:", aiAnalysis.message);

            // Use the AI-fixed data if provided, otherwise use original
            const submissionData = aiAnalysis.fixedData || formData;

            toast({
              title: "Intelligent Validation",
              description: aiAnalysis.message,
              variant: "default",
            });

            // Proceed with the submission using AI-enhanced data
            await submitRequest(parseInt(params.id), submissionData);

            toast({
              title: "Success",
              description: "Request submitted for approval with AI assistance",
              variant: "default",
            });

            setLocation("/");
            return;
          } else {
            // AI recommends not proceeding - show the validation errors
            toast({
              title: "Validation Error",
              description: aiAnalysis.message || (validationErrors.length > 0 ? validationErrors[0] : "Please check all required fields"),
              variant: "destructive",
              className: "animate-error",
            });

            // If there are multiple errors, log them
            if (validationErrors.length > 1) {
              console.error("Additional validation errors:", validationErrors.slice(1));
            }
            return;
          }
        } catch (error) {
          console.error("Error analyzing validation context:", error);

          // Fall back to default validation behavior
          toast({
            title: "Validation Error",
            description: validationErrors.length > 0 ? validationErrors[0] : "Please check all required fields",
            variant: "destructive",
            className: "animate-error",
          });

          if (validationErrors.length > 1) {
            console.error("Additional validation errors:", validationErrors.slice(1));
          }
          return;
        }
      }

      // All validation passed, proceed with submission
      console.log("Submitting request for approval with full validation");
      await onSubmit({
        ...currentValues,
        status
      });
    } catch (error: any) {
      console.error("Submit error:", error);
      toast({
        title: "Error",
        description: "Failed to submit form",
        variant: "destructive",
        className: "animate-error",
      });
    }
  }, [form, onSubmit, toast, items, freightAmount, selectedVendor, totalCost, params.id, setLocation]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#7058a3]/5 to-[#3eb6ba]/5 py-8">
      <div className="max-w-4xl mx-auto px-4">
        <Button
          variant="ghost"
          className="mb-6 group hover:bg-[#7058a3]/10 transition-all duration-200 rounded-lg"
          onClick={() => setLocation("/")}
        >
          <ArrowLeft className="h-4 w-4 mr-2 group-hover:-translate-x-1 transition-transform" />
          <span className="text-[#7058a3] font-medium">Back to Dashboard</span>
        </Button>

        {isLoading ? (
          <Card className="border-[#3eb6ba]/20 shadow-lg">
            <CardContent className="pt-6">
              <div className="flex justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-[#7058a3]" />
              </div>
            </CardContent>
          </Card>
        ) : (
          <Card className="border-[#3eb6ba]/20 shadow-lg hover:shadow-xl transition-shadow duration-300">
            <CardHeader className="border-b border-[#3eb6ba]/20 bg-gradient-to-r from-[#7058a3]/5 to-[#3eb6ba]/5">
              <CardTitle className="text-[#7058a3] text-2xl font-bold">
                Edit Purchase Request
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 grid gap-6">
              <Form {...form}>
                <form className="space-y-6" onSubmit={(e) => e.preventDefault()}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Basic Information Section */}
                    <div className="space-y-6 p-6 bg-white rounded-xl shadow-sm border border-[#3eb6ba]/20 hover:border-[#3eb6ba]/40 transition-colors">
                      <h3 className="text-lg font-semibold text-[#7058a3] mb-4 flex items-center">
                        <span className="w-1.5 h-6 bg-[#7058a3] rounded-r mr-2"></span>
                        Basic Information
                      </h3>
                      <FormField
                        control={form.control}
                        name="title"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[#7058a3]">Request Title</FormLabel>
                            <FormControl>
                              <Input
                                {...field}
                                className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="description"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[#7058a3]">Description</FormLabel>
                            <FormControl>
                              <Textarea
                                {...field}
                                className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>

                    {/* Request Type Section */}
                    <div className="space-y-6 p-6 bg-white rounded-xl shadow-sm border border-[#3eb6ba]/20 hover:border-[#3eb6ba]/40 transition-colors">
                      <h3 className="text-lg font-semibold text-[#7058a3] mb-4 flex items-center">
                        <span className="w-1.5 h-6 bg-[#7058a3] rounded-r mr-2"></span>
                        Request Type
                      </h3>
                      <div className="grid grid-cols-2 gap-6">
                        <FormField
                          control={form.control}
                          name="purposeType"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-[#7058a3]">Purpose Type</FormLabel>
                              <Select 
                                onValueChange={(value) => {
                                  // Reset subPurposeId when purpose type changes
                                  form.setValue("subPurposeId", null);
                                  field.onChange(value);
                                }} 
                                value={field.value}
                              >
                                <FormControl>
                                  <SelectTrigger className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring">
                                    <SelectValue placeholder="Select purpose type" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  <SelectItem value="E3 EVENT">E3 EVENT</SelectItem>
                                  <SelectItem value="PROJECT">Project</SelectItem>
                                  <SelectItem value="MALL">Mall</SelectItem>
                                  <SelectItem value="BUSINESS GROWTH">Business Growth</SelectItem>
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />

                        <FormField
                          control={form.control}
                          name="priority"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-[#7058a3]">Priority</FormLabel>
                              <Select onValueChange={field.onChange} value={field.value}>
                                <FormControl>
                                  <SelectTrigger className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring">
                                    <SelectValue placeholder="Select priority" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  {priorities.map(({ label, value }) => (
                                    <SelectItem key={value} value={value}>
                                      {label}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />

                        <FormField
                          control={form.control}
                          name="subPurposeId"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-[#7058a3]">Sub-purpose</FormLabel>
                              <FormControl>
                                <SubPurposeSelect
                                  purposeType={form.watch("purposeType")}
                                  value={field.value ?? undefined}
                                  onChange={field.onChange}
                                />
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>
                  </div>

                  {/* Items Section */}
                  <div className="space-y-6 p-6 bg-white rounded-xl shadow-sm border border-[#3eb6ba]/20 hover:border-[#3eb6ba]/40 transition-colors">
                    <div className="flex justify-between items-center mb-4">
                      <h3 className="text-lg font-semibold text-[#7058a3] flex items-center">
                        <span className="w-1.5 h-6 bg-[#7058a3] rounded-r mr-2"></span>
                        Items
                      </h3>
                      <div className="flex items-center gap-4">
                        <FormField
                          control={form.control}
                          name="currency"
                          render={({ field }) => (
                            <FormItem>
                              <Select onValueChange={field.onChange} value={field.value}>
                                <FormControl>
                                  <SelectTrigger className="w-[100px] border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring">
                                    <SelectValue />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  {currencies.map(({ label, value }) => (
                                    <SelectItem key={value} value={value}>
                                      {label}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                            </FormItem>
                          )}
                        />
                        <Button
                          type="button"
                          variant="outline"
                          onClick={addItem}
                          className="border-[#3eb6ba] text-[#3eb6ba] hover:bg-[#3eb6ba]/10 interactive-bounce"
                        >
                          <Plus className="h-4 w-4 mr-2" />
                          Add Item
                        </Button>
                      </div>
                    </div>

                    <div className="space-y-4">
                      {items.map((item, index) => (
                        <div
                          key={index}
                          className="flex gap-4 items-start p-4 rounded-lg border border-[#7058a3]/10 hover:border-[#7058a3]/30 transition-colors animate-fade-in"
                        >
                          <div className="flex-1 space-y-2">
                            <Input
                              placeholder="Item name"
                              value={item.name}
                              onChange={(e) => updateItem(index, "name", e.target.value)}
                              className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                            />
                            <Textarea
                              placeholder="Item description (optional)"
                              value={item.description}
                              onChange={(e) => updateItem(index, "description", e.target.value)}
                              className="border-[#7058a3]/20 focus:border-[#7058a3] h-20 form-focus-ring"
                            />
                          </div>
                          <div className="w-24">
                            <Input
                              type="number"
                              step="0.01"
                              min="0.01"
                              placeholder="Qty"
                              value={item.quantity}
                              onChange={(e) => updateItem(index, "quantity", e.target.value)}
                              className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                            />
                          </div>
                          <div className="w-32">
                            <Input
                              type="number"
                              step="0.01"
                              min="0.01"
                              placeholder="Cost"
                              value={item.estimatedCost}
                              onChange={(e) => updateItem(index, "estimatedCost", e.target.value)}
                              className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                            />
                          </div>
                          <div className="w-32 text-right">
                            <p className="text-sm text-[#7058a3]">
                              {form.watch("currency")} {(item.quantity * item.estimatedCost).toFixed(2)}
                            </p>
                          </div>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            onClick={() => removeItem(index)}
                            disabled={items.length === 1}
                            className="text-red-500 hover:text-red-700 hover:bg-red-50 interactive-bounce"
                          >
                            <Trash className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                    </div>

                    <div className="mt-6 p-4 rounded-lg bg-gradient-to-r from-[#7058a3]/5 to-[#3eb6ba]/5">
                      <FormItem>
                        <FormLabel className="text-[#7058a3]">Freight Amount</FormLabel>
                        <FormControl>
                          <Input
                            type="number"
                            min="0"
                            step="0.01"
                            value={freightAmount}
                            onChange={(e) => setFreightAmount(Number(e.target.value))}
                            className="border-[#7058a3]/20 focus:border-[#7058a3] form-focus-ring"
                          />
                        </FormControl>
                      </FormItem>

                      <div className="mt-4 space-y-2">
                        <div className="flex justify-between text-[#7058a3]">
                          <span>Items Total:</span>
                          <span>
                            {form.watch("currency")} {items
                              .reduce(
                                (sum, item) => sum + item.quantity * item.estimatedCost,
                                0
                              )
                              .toFixed(2)}
                          </span>
                        </div>
                        <div className="flex justify-between text-[#7058a3]">
                          <span>Freight Amount:</span>
                          <span>{form.watch("currency")} {freightAmount.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between pt-2 border-t border-[#7058a3]/20">
                          <span className="text-lg font-semibold text-[#7058a3]">
                            Total Estimated Cost:
                          </span>
                          <span className="text-lg font-bold text-[#7058a3]">
                            {form.watch("currency")} {totalCost.toFixed(2)}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Vendor Information Section */}
                  <div className="space-y-6 p-6 bg-white rounded-xl shadow-sm border border-[#3eb6ba]/20 hover:border-[#3eb6ba]/40 transition-colors">
                    <h3 className="text-lg font-semibold text-[#7058a3] mb-4 flex items-center">
                      <span className="w-1.5 h-6 bg-[#7058a3] rounded-r mr-2"></span>
                      Vendor Information
                    </h3>
                    <div>
                      <FormItem>
                        <FormLabel className="text-[#7058a3]">Vendor Selection</FormLabel>
                        <p className="text-xs text-gray-500 mb-2">Select a vendor from the list. Vendor details cannot be edited here.</p>
                        <FormControl>
                          <VendorSelect 
                            value={selectedVendor}
                            onChange={(vendorId) => setSelectedVendor(vendorId)}
                            onVendorCreated={handleVendorCreated}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>

                      {selectedVendor && (
                        <div className="mt-4 p-4 rounded-lg bg-slate-50 border border-slate-200">
                          <h4 className="font-medium text-[#7058a3] mb-2">Vendor Details (Read Only)</h4>
                          <p className="text-xs text-gray-500 mb-3">These details are displayed for reference only and cannot be modified here.</p>
                          <div className="grid grid-cols-2 gap-3 text-sm">
                            {/* Display vendor details if a vendor is selected */}
                            {request?.vendor && (
                              <>
                                <div>
                                  <p className="font-medium text-slate-700">Company Name:</p>
                                  <p className="text-slate-600">{request.vendor.companyName || "Not specified"}</p>
                                </div>
                                <div>
                                  <p className="font-medium text-slate-700">Contact Person:</p>
                                  <p className="text-slate-600">{request.vendor.contactPerson || "Not specified"}</p>
                                </div>
                                <div>
                                  <p className="font-medium text-slate-700">Contact Number:</p>
                                  <p className="text-slate-600">{request.vendor.contactNumber || "Not specified"}</p>
                                </div>
                                <div>
                                  <p className="font-medium text-slate-700">Email:</p>
                                  <p className="text-slate-600">{request.vendor.email || "Not specified"}</p>
                                </div>
                              </>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex justify-between pt-6">
                    <Button
                      type="button"
                      onClick={() => handleSubmit("draft")}
                      variant="outline"
                      className="border-[#3eb6ba] text-[#3eb6ba] hover:bg-[#3eb6ba]/10 transition-colors"
                    >
                      Save as Draft
                    </Button>
                    <Button
                      type="button"
                      onClick={() => handleSubmit("pending")}
                      className="bg-[#7058a3] hover:bg-[#7058a3]/90 text-white transition-colors"
                    >
                      Submit for Approval
                    </Button>
                  </div>
                </form>
              </Form>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

