/* Minimal animations.css - ultra lightweight version */

/* Essential loading animation - keep for UX feedback */
.loading-spin {
  border: 2px solid hsla(var(--muted));
  border-top-color: hsla(var(--primary));
  border-radius: 50%;
  width: 1.25em;
  height: 1.25em;
  animation: spin 0.8s linear infinite;
}

/* Accessible form focus */
.form-focus-ring:focus-within {
  box-shadow: 0 0 0 2px hsla(var(--primary), 0.2);
}

/* Better text visibility - no animations */
.text-enhanced {
  color: hsla(var(--foreground), 0.95);
  font-weight: 500;
}

/* Simplified toast notifications - essential for UX */
.toast-enter {
  transform: translateY(5px);
  opacity: 0;
}

.toast-enter-active {
  transform: translateY(0);
  opacity: 1;
  transition: transform 0.2s ease-out, opacity 0.2s ease-out;
}

.toast-exit-active {
  opacity: 0;
  transition: opacity 0.2s ease-out;
}

/* Only essential keyframes */
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

